      '时雨': '时雨',
      '伊吕波': '伊吕波',
      '妃咲': '妃咲',
      '芹奈': '芹奈'
    };

    // 当前选中的学生
    let selectedCharacter = null;

    // DOM 元素
    const studentsGrid = document.getElementById('studentsGrid');
    const starterBtn = document.getElementById('starterBtn');
    const randomBtn = document.getElementById('randomBtn');
    const characterName = document.getElementById('characterName');
    const characterArtwork = document.getElementById('characterArtwork');
    const startBtn = document.getElementById('startBtn');
    const copyBtn = document.getElementById('copyBtn');
    const toast = document.getElementById('toast');

    // 初始化学生网格
    function initStudentsGrid() {
      const characters = Object.keys(characterScenarios);
      const sortedCharacters = [
        ...featuredCharacters.filter(char => characters.includes(char)),
        ...characters.filter(char => !featuredCharacters.includes(char))
      ];

      sortedCharacters.forEach(char => {
        const card = document.createElement('div');
        card.className = 'student-card';
        const hasIllustration = featuredCharacters.includes(char);
        if (hasIllustration) {
          card.classList.add('starred');
          card.setAttribute('aria-label', `${char}（有插画）`);
        }
        card.dataset.character = char;
        card.innerHTML = `<span class="student-name">${char}</span>`;
        card.onclick = () => selectCharacter(char, card);
        studentsGrid.appendChild(card);
      });
    }

    // 选择学生
    function selectCharacter(character, cardElement) {
      selectedCharacter = character;

      // 更新选中状态
      document.querySelectorAll('.student-card').forEach(card => {
        card.classList.remove('active');
      });
      cardElement.classList.add('active');

      // 更新角色名称
      const displayName = characterFullNames[character] || character;
      characterName.textContent = displayName;
      characterName.classList.remove('placeholder');

      // 更新角色立绘
      updateCharacterArtwork(character);

      // 启用按钮
      startBtn.disabled = false;
      copyBtn.disabled = false;
    }

    // 更新角色立绘
    function updateCharacterArtwork(character) {
      const imageName = characterImages[character];
      if (!imageName) {
        characterArtwork.innerHTML = '<div class="placeholder-text">暂无立绘</div>';
        return;
      }

      const imageUrl = `${coverBaseUrl}${encodeURIComponent(imageName)}.webp`;

      // 显示加载动画
      characterArtwork.innerHTML = '<div class="loading-spinner"></div>';

      const img = new Image();
      img.className = 'character-image';
      img.src = imageUrl;

      img.onload = () => {
        characterArtwork.innerHTML = '';
        characterArtwork.appendChild(img);
        setTimeout(() => img.classList.add('loaded'), 50);
      };

      img.onerror = () => {
        characterArtwork.innerHTML = '<div class="placeholder-text">立绘加载失败</div>';
      };
    }

    // 开始游戏（发送消息到 SillyTavern）
    startBtn.onclick = function() {
      if (!selectedCharacter) return;

      const message = characterScenarios[selectedCharacter];

      if (sendMessageToChat(message)) {
        showToast('开局已发送！', 'success');
      }
    };

    // 复制文本
    copyBtn.onclick = function() {
      if (!selectedCharacter) return;

      const message = characterScenarios[selectedCharacter];

      navigator.clipboard.writeText(message).then(() => {
        showToast('文本已复制到剪贴板！', 'success');
      }).catch(err => {
        showToast('复制失败：' + err.message, 'error');
      });
    };

    // 发送消息到 SillyTavern
    function sendMessageToChat(message) {
      try {
        console.log('📤 准备发送消息到 SillyTavern:', message);

        // 尝试从父窗口获取元素（如果在 iframe 中）
        let targetDocument = document;
        if (window.parent && window.parent !== window) {
          try {
            targetDocument = window.parent.document;
            console.log('📱 检测到 iframe 环境，使用父窗口 document');
          } catch (e) {
            console.warn('⚠️ 无法访问父窗口，使用当前 document');
          }
        }

        const textarea = targetDocument.getElementById('send_textarea');
        const sendButton = targetDocument.getElementById('send_but');

        if (!textarea || !sendButton) {
          console.error('❌ 找不到 SillyTavern 的输入框或发送按钮');
          showToast('无法发送消息：找不到 SillyTavern 的输入元素', 'error');
          return false;
        }

        // 设置消息内容
        textarea.value = message;

        // 触发输入事件
        const inputEvent = new Event('input', { bubbles: true });
        textarea.dispatchEvent(inputEvent);

        // 点击发送按钮
        sendButton.click();

        console.log('✅ 消息已发送');
        return true;
      } catch (error) {
        console.error('❌ 发送消息失败:', error);
        showToast('发送消息失败：' + error.message, 'error');
        return false;
      }
    }

    // 显示提示消息
    function showToast(message, type = 'success') {
      toast.textContent = message;
      toast.className = `toast ${type} show`;

      setTimeout(() => {
        toast.classList.remove('show');
      }, 3000);
    }

    // 初始化
    initStudentsGrid();

    // 随机选择按钮
    starterBtn.onclick = function() {
      const targetCard = document.querySelector('.student-card[data-character="阿罗娜"]');
      if (!targetCard) {
        showToast('找不到阿罗娜，稍后再试', 'error');
        return;
      }
      selectCharacter('阿罗娜', targetCard);
      showToast('已切换到故事起点', 'success');
      targetCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
    };

    randomBtn.onclick = function() {
      const cards = Array.from(document.querySelectorAll('.student-card'));
      if (!cards.length) return;
      const randomCard = cards[Math.floor(Math.random() * cards.length)];
      const character = randomCard.dataset.character;
      selectCharacter(character, randomCard);
      showToast(`已随机选择 ${character}`, 'success');
    };
  </script>
</body>
</html>
