    body[data-theme="dark"] .detail-skill-card {
      background: rgba(255, 255, 255, 0.05);
    }

    .detail-skill-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 12px;
    }

    .detail-skill-type {
      font-size: 16px;
      font-weight: 600;
      color: #5BA4E5;
