    /* ========== 学生选择弹窗样式 ========== */
    .student-selector-modal {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.8);
      z-index: 10000;
      justify-content: center;
      align-items: center;
      animation: fadeIn 0.3s ease;
      overflow-y: auto;
      padding: 20px;
    }

    .student-selector-modal.active {
      display: flex;
    }

    .student-selector-content {
      background: var(--paper);
      border-radius: 16px;
      max-width: 1200px;
      width: 100%;
      max-height: 85vh;
      min-height: 600px;
      overflow-y: auto;
      position: relative;
      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
      animation: slideInUp 0.3s ease;
    }

    body[data-theme="dark"] .student-selector-content {
      background: rgba(15, 23, 42, 0.98);
    }

    .student-selector-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 20px 30px;
      border-bottom: 2px solid var(--line);
      position: sticky;
      top: 0;
      background: var(--paper);
      z-index: 10;
    }

    body[data-theme="dark"] .student-selector-header {
      background: rgba(15, 23, 42, 0.98);
    }

    .student-selector-header h3 {
      margin: 0;
      font-size: 20px;
      color: var(--ink);
    }

    .student-selector-close {
      font-size: 32px;
      color: var(--muted);
      cursor: pointer;
      width: 40px;
      height: 40px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 50%;
      /* 性能优化: 指定具体transition属性 */
      transition: transform 0.3s ease, opacity 0.3s ease, box-shadow 0.3s ease;
    }

    .student-selector-close:hover {
      background: rgba(0, 0, 0, 0.1);
      color: var(--ink);
      transform: rotate(90deg);
    }

    body[data-theme="dark"] .student-selector-close:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    .student-selector-body {
      padding: 20px 30px 30px;
    }

    .student-selector-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 16px;
    }

    .selector-student-card {
      background: #F8FBFD;
      border: 2px solid #E1EBF4;
      border-radius: 8px;
      overflow: hidden;
      cursor: pointer;
      /* 性能优化: 指定具体transition属性 */
      transition: transform 0.3s ease, opacity 0.3s ease, box-shadow 0.3s ease;
    }

    .selector-student-card:hover {
      border-color: #5BA4E5;
      box-shadow: 0 4px 16px rgba(91, 164, 229, 0.2);
      transform: translateY(-4px);
    }

    body[data-theme="dark"] .selector-student-card {
      background: rgba(15, 23, 42, 0.6);
      border-color: rgba(255, 255, 255, 0.1);
    }

    body[data-theme="dark"] .selector-student-card:hover {
      border-color: #5BA4E5;
      background: rgba(15, 23, 42, 0.8);
    }

    .selector-student-avatar {
      height: 140px;
      background: linear-gradient(to bottom, #D9EAFC, #EDF4FA);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 60px;
      position: relative;
    }

    .selector-student-avatar.has-cover {
      background-size: cover;
      background-position: center;
      background-repeat: no-repeat;
    }

    .selector-student-info {
      padding: 12px;
    }

    .selector-student-name {
      font-size: 15px;
      font-weight: 600;
      color: var(--ink);
      margin-bottom: 8px;
      text-align: center;
    }

    .selector-student-meta {
      display: flex;
      flex-direction: column;
      gap: 4px;
      font-size: 12px;
      color: var(--muted);
    }

    .selector-meta-row {
      display: flex;
      justify-content: space-between;
    }

    /* 离队按钮样式 */
    .leave-team-btn {
      position: absolute;
      top: 60px;
      right: 20px;
      background: linear-gradient(135deg, #ef4444, #dc2626);
      color: white;
      border: none;
      padding: 8px 16px;
      border-radius: 20px;
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 6px;
      /* 性能优化: 指定具体transition属性 */
      transition: transform 0.3s ease, opacity 0.3s ease, box-shadow 0.3s ease;
      box-shadow: 0 2px 8px rgba(239, 68, 68, 0.3);
      z-index: 10001;
    }

    .leave-team-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 4px 12px rgba(239, 68, 68, 0.4);
      background: linear-gradient(135deg, #dc2626, #b91c1c);
    }

    .leave-team-btn:active {
      transform: translateY(0);
    }

    /* 响应式 */
    @media (max-width: 1200px) {
      .team-grid {
        grid-template-columns: repeat(auto-fit, minmax(220px, 300px));
      }
      .stats-grid {
        grid-template-columns: repeat(2, 1fr);
      }
      .enemies-grid {
        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
      }
      .team-battle-grid {
        grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
      }
    }

