    // ========== 生产环境console优化 ==========
    (function() {
      const isProduction = !window.location.hostname.includes('localhost') &&
                          !window.location.hostname.includes('127.0.0.1');

      if (isProduction) {
        // 生产环境禁用console（保留error和warn）
        const noop = function() {};
        console.log = noop;
        console.debug = noop;
        console.info = noop;
      }
    })();


    // ========== requestIdleCallback Polyfill（兼容移动端）==========
    (function() {
      if (!('requestIdleCallback' in window)) {
        window.requestIdleCallback = function(callback, options) {
          const start = Date.now();
          const timeout = (options && typeof options.timeout === 'number') ? options.timeout : 1;
          return setTimeout(() => {
            callback({
              didTimeout: false,
              timeRemaining: function() {
                return Math.max(0, 50 - (Date.now() - start));
              }
            });
          }, timeout);
        };
      }
      if (!('cancelIdleCallback' in window)) {
        window.cancelIdleCallback = function(id) {
          clearTimeout(id);
        };
      }
    })();

    // ========== 延迟执行框架（优化首次渲染）==========
    const deferredTasks = [];

    window.deferTask = function(task, priority = 'low') {
      deferredTasks.push({ task, priority });
    };

    // 在load事件后执行低优先级任务
    window.addEventListener('load', () => {
      const lowPriorityTasks = deferredTasks.filter(t => t.priority === 'low');

      lowPriorityTasks.forEach(({ task }, index) => {
        if (window.requestIdleCallback) {
          requestIdleCallback(task, { timeout: 2000 + index * 100 });
        } else {
          setTimeout(task, index * 100);
        }
      });
    });

