      .stats-grid {
        grid-template-columns: repeat(2, 1fr);
      }
      .enemies-grid {
        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
      }
      .team-battle-grid {
        grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
      }
    }

