      // ========== 公共工具函数（提取重复代码）==========

      // 解析技能字符串（简化版，用于卡片显示）
      function parseSkill(skillContent) {
        if (!skillContent) return { name: '未设置', description: '' };
        // 确保 skillContent 是字符串类型
        const skillStr = String(skillContent);
        // 兼容格式：【技能名|等级|cost|描述|...】
        // 提取第1个字段（技能名）和第4个字段（描述）
        const match = skillStr.match(/【([^|]+)\|[^|]*\|[^|]*\|([^|]+)/);
        if (match) {
