            <div class="student-battle-level">LV ${student.combat_stats.level}</div>
          </div>

          <div class="student-hp-bar">
            <div class="student-hp-label">
              <span>生命值</span>
              <span>${student.combat_stats.hp.current} / ${student.combat_stats.hp.max}</span>
