      // 全局Escape键处理
      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
          const detailModal = document.getElementById('studentDetailModal');
          if (detailModal && detailModal.classList.contains('active')) {
            closeStudentDetail();
