---
{
  "locationProfile": {
    "id": "sweetsClub",
    "name": "放学后甜点部 (After-School Sweets Club)",
    "function": "隶属于三一综合学园。名义上是品尝甜点、享受茶会的悠闲社团，实则是在『正义实现委员会』委托下处理各类棘手事件的非正式武装小队。她们以“下课后回家”为信条，战斗的最终目的往往是为了能安心地享用甜点。",
    "involvedCharacters": [
      {
        "name": "杏山和纱 (Kazusa Kyoyama)",
        "role": "实际上的领队，外冷内热，实力强大。",
        "appearance": "黑色短发，发尾挑染成粉色，拥有一对黑色的猫耳。红色眼瞳。表情冷淡，看起来有些不好接近，但实际上是个内心温柔、喜欢猫的少女，是社团的隐藏王牌。"
      },
      {
        "name": "伊原木爱理 (Airi Ihara)",
        "role": "负责制作点心，是团队中温柔善良的核心。",
        "appearance": "深棕色中长发，绿色眼瞳。脸上总是带着温柔亲切的笑容。性格极其善良，擅长制作各种点心，是甜点部中负责凝聚大家的核心人物。"
      },
      {
        "name": "柚鸟夏 (Natsu Yutori)",
        "role": "充满活力的气氛制造者，对美食充满热情。",
        "appearance": "粉色长发扎成高高的双马尾，红色眼瞳。性格天真烂漫、充满活力，是甜点部的气氛制造者。对美食抱有极大的热情，思考方式非常直接。"
      },
      {
        "name": "栗村好美 (Yoshimi Kurimura)",
        "role": "傲娇的吐槽役，非常关心同伴。",
        "appearance": "金色长发扎成双马尾，拥有一对金色的猫耳。棕色眼瞳。典型的傲娇性格，嘴上总是抱怨，但实际上非常关心同伴，是团队的吐槽役和火力支援担当。"
      }
    ],
    "environment": {
      "physical": "活动地点不固定，除了在三一校内的温馨社团活动室外，她们的足迹遍布基沃托斯各处的甜品店、咖啡馆乃至战斗前线。",
      "socialAtmosphere": "三一内部一片“绿洲”般的存在。社团氛围极其友爱和睦，成员间如同家人般亲密，充满了轻松、治愈的日常感。即使在紧张的战斗中，她们的对话也离不开甜点，是三一严肃政治氛围下的一抹亮色。"
    }
  }
}

