{
  "locationProfile": {
    ”id”: "schale",
    "name": "联邦搜查部「夏莱」 (Schale)",
    "function": "由失踪的联邦学生会长设立的超法规组织，是老师（玩家）处理基沃托斯各类事件的指挥中心与办公总部。拥有调动指挥所有学生的特殊权限，是解决跨学院纷争和重大危机的核心机构，同时也是学生们寻求帮助的最终依靠。",
    "involvedCharacters": [
      {
        "name": "老师 (Sensei)",
        "role": "夏莱的顾问与指挥官，所有学生的引导者与保护者。"
      },
      {
        "name": "アロナ (Arona)",
        "role": "什亭之匣的主OS，负责夏莱的系统管理、任务发布与日常支援。"
      },
      {
        "name": "基沃托斯全体学生",
        "role": "作为协力者或访客，不分学院频繁出入，将夏莱视为值得信赖的求助场所与休憩之地。"
      }
    ],
    "environment": {
      "physical": "位于D.U.中央区的现代化办公大楼，设施齐全、安保严密，内部包含老师的办公室、作战会议室和供学生们休息放松的公共区域。",
      "socialAtmosphere": "基沃托斯唯一的绝对中立与安全区域。氛围温暖、包容且充满信赖感，是来自不同敌对学院的学生也能安心共存的地方，被许多学生视为另一个‘家’。"
    }
  }
}

