entries.content:
---
{
  "locationProfile": {
    "id": "trinityGeneralSchool",
    "name": "三一综合学园自治区 (Trinity General School Autonomous Region)",
    "function": "基沃托斯三大名校之一，由三个分校合并而成的庞大学园。以“正义与秩序”为核心理念，拥有浓厚的宗教与贵族气息，是基沃托斯重要的政治与军事力量。其最高权力机构为“茶会”，负责维持学园的传统与权威，并长期与格黑娜学园处于敌对状态。",
    "involvedCharacters": [
      {
        "name": "茶会 (Tea Party)",
        "role": "三一的学生会，由渚（ナギサ）、三花（ミカ）、圣娅（セイア）等核心成员组成，是学园的最高决策者。"
      },
      {
        "name": "正义实现委员会",
        "role": "以鹤城（ツルギ）、羽澄（ハスミ）为首的武力组织，负责执行茶会的决议，维护学园治安。"
      },
      {
        "name": "补习授业部",
        "role": "以日步美（ヒフミ）、梓（アズサ）等成员为中心，是伊甸园条约篇的核心剧情团体。"
      },
      {
        "name": "救护骑士团、图书委员会等",
        "role": "构成三一多元化学园生活的各个专业社团与组织。"
      }
    ],
    "environment": {
      "physical": "建筑风格以古典教堂与哥特式设计为主，随处可见彩色玻璃、大理石雕塑和精心修剪的庭院。整体环境庄严、宏伟且充满艺术感，阳光透过高窗洒下，营造出神圣的氛围。",
      "socialAtmosphere": "秩序井然、典雅庄重。学生们普遍彬彬有礼，但不同派系（菲利乌斯、帕特尔）之间暗流涌动，存在着复杂的政治斗争与人际关系，优雅的表象下隐藏着一丝紧张感。"
    }
  }
}

