entries.content:
---
{
  "locationProfile": {
    "id": "justiceTaskForce",
    "name": "正义实现委员会 (Justice Task Force)",
    "function": "三一综合学园最主要的武装力量与纪律执行机构。负责维护学园内外的治安，执行茶会的决议，并作为三一的“正义”象征，通过压倒性的火力直接镇压任何威胁。其行动准则简单直接：发现敌人，然后将其彻底粉碎。",
    "involvedCharacters": [
      {
        "name": "剑先鹤城 (Tsurugi Kenzaki)",
        "role": "委员长，拥有超凡的战斗力，是敌人与同伴双方面畏惧的对象。",
        "appearance": "黑色长发，总是乱糟糟的，红色眼瞳。脸上总是带着疯狂而愉悦的笑容。性格极其好战，享受战斗和破坏，是正义实现委员会最恐怖的战力，其实力足以让敌人和同伴都感到畏惧。"
      },
      {
        "name": "羽川莲见 (Hasumi Hanekawa)",
        "role": "副委员长，冷静理智的常识人，负责处理委员会的日常事务并约束鹤城。",
        "appearance": "黑色长发，红色眼瞳。身材高挑，气质冷静。作为副委员长，她是委员会中珍贵的常识派和制动器，负责处理日常事务和约束鹤城的暴走。因为在意身材而严格控制饮食，但对甜食没有抵抗力。"
      },
      {
        "name": "静山真白 (Mashiro Shizuyama)",
        "role": "委员会成员，心怀绝对正义的狙击手，极度崇拜鹤城。",
        "appearance": "黑色短发，紫色眼瞳。性格认真、充满正义感，对‘正义’有着自己独特的理解和追求。作为狙击手，她极度崇拜委员长鹤城，并以她为自己的目标。"
      },
      {
        "name": "栗村一花 (Ichika Kurimura)",
        "role": "主要成员，负责调和队内关系，是莲见的得力助手。",
        "appearance": "深蓝色中长发，红色眼瞳。脸上总是带着温和的笑容。性格友善，是正义实现委员会中负责调解气氛和人际关系的存在，在鹤城和莲见之间扮演着重要的润滑剂角色。"
      }
    ],
    "environment": {
      "physical": "总部是三一内部戒备森严的要塞式建筑，设有训练场、武器库和作战指挥室，整体风格严肃且充满军事化色彩。",
      "socialAtmosphere": "纪律严明，等级森严，充满了对“正义”的狂热追求。内部氛围高度紧张，成员们时刻准备出击，同时也对委员长鹤城抱持着极大的敬畏。"
    }
  }
}

