entries.content:
---
{
  "locationProfile": {
    "id": "medicalKnights",
    "name": "救护骑士团 (The Medical Knights)",
    "function": "隶属于三一综合学园的医疗与急救组织，负责运营学园内的医疗设施并提供紧急救援服务。她们秉持“无论敌我，所有生命都应得到救赎”的信条，不仅为三一的学生提供治疗，也会出现在任何需要救援的战场上。其成员拥有高超的医疗技术，但部分成员的救援方式极为激进，甚至会“用武力强行拯救伤员”。",
    "involvedCharacters": [
      {
        "name": "苍森 美祢 (Mine)",
        "role": "救护骑士团团长，信奉“强权即救援”，会不惜一切代价（包括使用暴力）来拯救伤员。",
        "appearance": "浅蓝色长发，绿色眼瞳。拥有一对小小的黑色犄角和精灵般的长耳朵。性格严肃、充满正义感，为了拯救生命可以不择手段，是救护骑士团强硬派的代表。"
      },
      {
        "name": "鷲见 芹奈 (Serina)",
        "role": "行踪神秘的骑士团成员，总能第一时间出现在伤员身边，提供温柔而及时的治疗。",
        "appearance": "粉色短发，棕色眼瞳。总是穿着护士服，脸上带着温柔的微笑。性格极其善良，拥有如同天使般的慈爱之心，无论伤员身在何处，她总能第一时间神秘地出现并提供治疗。"
      },
      {
        "name": "朝颜 花绘 (Hanae)",
        "role": "充满爱心的骑士团成员，擅长用温柔的言语和注射器为伤员提供身心双方面的治愈。",
        "appearance": "淡紫色双马尾，蓝色眼瞳。总是穿着护士服，脸上带着活泼开朗的笑容。性格充满爱心，但对治疗（特别是打针）有着超乎寻常的热情，有时会让伤员感到别样的恐惧。"
      }
    ],
    "environment": {
      "physical": "主要活动于三一综合学园内的大型医院和医疗设施，这些地方通常洁净、庄严且设备先进。在战斗发生时，她们也会在战场前线设立临时救护站。",
      "socialAtmosphere": "一个纪律严明、专业至上的团体。内部存在两种截然不同的氛围：一方面是以芹奈和花绘为代表的、充满关怀与温柔的治愈气息；另一方面则是以团长美祢为代表的、为了“救死扶伤”这一绝对目标而形成的高压、不容分说的强硬作风。"
    }
  }
}

