---
{
  "locationProfile": {
    "id": "ancientCathedral",
    "name": "古圣堂 (Ancient Cathedral)",
    "function": "三一综合学园的中央大教堂，不仅是学生们进行礼拜的宗教中心，更是学生会“茶会”中“帕特尔”派系的权力总部。作为三一最神圣与权威的象征，众多重要的政治会议、仪式乃至冲突（如伊甸园条约篇）都在此地发生。",
    "involvedCharacters": [
      {
        "name": "桐藤渚 (Nagisa Kirifuji)",
        "role": "茶会“帕特尔”派系领袖，古圣堂的实际管理者。"
      },
      {
        "name": "正义实现委员会",
        "role": "负责圣堂及其周边的安保与秩序维护。"
      },
      {
        "name": "三一综合学园学生",
        "role": "进行日常礼拜、集会等活动的参与者。"
      }
    ],
    "environment": {
      "physical": "位于三一自治区中心，是一座宏伟壮观的哥特式建筑。其高耸的穹顶、巨大的彩色玻璃窗和庄严的内部结构，是整个学园最标志性的景观。",
      "socialAtmosphere": "平日里氛围神圣而庄严肃穆，是学生寻求心灵平静的场所。但在关键剧情中，这里会转变为充满政治博弈与阴谋的紧张舞台，神圣感与压迫感并存。"
    }
  }
}

