entries.content:
---
{
  "locationProfile": {
    "id": "sisterhood",
    "name": "修女会 (The Sisterhood)",
    "function": "三一综合学园两大势力之一，是以信仰为核心的宗教组织与武装力量。负责维护三一的传统、信仰与秩序，管理大教堂等宗教设施，并积极从事慈善救助活动。在政治上是保守派的代表，拥有足以与“茶会”抗衡的影响力。",
    "involvedCharacters": [
      {
        "name": "歌住樱子 (Utazumi Sakurako)",
        "role": "修女会会长，虔诚的领袖与执行者。",
        "appearance": "银白色长发，紫色眼瞳。身穿庄严的黑白修女服。性格极其认真、虔诚，严格遵守戒律，是修女会的领导者。为了维护三一的秩序，她会毫不犹豫地采取行动。"
      },
      {
        "name": "若叶日向 (Wakaba Hinata)",
        "role": "主要成员，负责后勤支援但拥有巨大破坏力。",
        "appearance": "黑色长发，红色眼瞳。身穿带有金色装饰的修女服。性格温柔善良，但有些冒失，总是想帮助别人却常常搞砸事情。虽然是后勤人员，却携带着拥有巨大破坏力的重型武器。"
      },
      {
        "name": "伊落玛丽 (Iochi Mari)",
        "role": "主要成员，热心于慈善与救助工作。",
        "appearance": "橙色中长发，蓝色眼瞳，拥有一对猫耳朵。身穿修女服。性格极其友善、充满慈爱，热心于各种慈善和志愿活动，在三一拥有很高的人气，是大家公认的“天使”。"
      }
    ],
    "environment": {
      "physical": "活动中心是宏伟庄严的三一总教堂。以古典的哥特式建筑为特征，内部装饰着华丽的彩色玻璃与宗教雕塑，光线昏暗而神圣。",
      "socialAtmosphere": "氛围虔诚、纪律严明且宁静肃穆。对外是可靠的庇护所与慈善机构，对内则坚守着严格的传统与戒律，是三一最保守与最坚定的秩序维护者。"
    }
  }
}

