---
{
  "locationProfile": {
    "id": "remedialKnights",
    "name": "补习部 (Remedial Knights)",
    "function": "三一综合学园为成绩不及格、面临退学危机的学生所设立的特别班级。名义上是“学习小组”，实则为了避免退学而进行强制补习。在伊甸园条约事件中，这个看似不起眼的团体意外地成为了守护基沃托斯和平的关键力量。",
    "involvedCharacters": [
      {
        "name": "阿慈谷日富美 (Ajitani Hifumi)",
        "role": "补习部的核心与粘合剂，外表平凡但内心坚强，拥有意外的行动力。",
        "appearance": "浅棕色短发，用黑黄相间的发带扎成侧马尾，棕色眼瞳。气质友善，看起来像一个非常普通的学生，但对‘佩洛洛’商品有着狂热的喜爱，在关键时刻会展现出惊人的行动力。"
      },
      {
        "name": "白洲梓 (Shirasu Azusa)",
        "role": "来自阿里乌斯分校的前突击队员，为了寻找“虚无以外的东西”而加入，战斗力极强。",
        "appearance": "白色长卷发，紫色眼瞳。总是面无表情，散发着忧郁和神秘的气质。虽然身材娇小，但作为前突击队员，她拥有顶尖的战斗技巧。"
      },
      {
        "name": "浦和花子 (Urawa Hanako)",
        "role": "因过于“色情”的行为而被流放的天才，拥有极高的智商与洞察力。",
        "appearance": "粉色长发，绿色眼瞳。脸上总是带着温柔而神秘的微笑。气质优雅，但言行举止总是充满着各种性暗示，因此被视为“行走的色情”，是三一天才中的异类。"
      },
      {
        "name": "下江小春 (Shimoe Koharu)",
        "role": "原正义实现委员会成员，因笔记内容不当而被迫加入，极度渴望成为“大人”。",
        "appearance": "粉色双马尾，头上戴着修女般的头巾，拥有一对小小的黑色犄角和粉色的眼瞳。性格保守，极度害怕‘色情’的事物，口头禅是‘死刑！’。但自己的笔记本里却画满了不健康的内容，是个充满矛盾的纯情少女。"
      }
    ],
    "environment": {
      "physical": "没有固定的活动室，主要在三一的普通教室、图书馆或户外进行学习。在伊甸园条约事件期间，她们曾在废墟中建立了一个临时的野营地作为秘密基地。",
      "socialAtmosphere": "一个由“问题学生”组成的奇妙团体。氛围充满了日常的吵闹、吐槽和对不及格的焦虑，但在关键时刻，成员之间会爆发出超越派系与出身的深厚信赖与友情，是“边缘人”找到归属感的温暖小团体。"
    }
  }
}

