{
  "locationProfile": {
    "id": "teaPartyCourtyard",
    "name": "茶会庭院 (Tea Party Courtyard)",
    "function": "三一综合学园的最高权力机构与决策中心。“茶会”的三位领导者在此地会晤，决定整个学园的方针与政策，是三一所有政治与权谋的舞台。",
    "involvedCharacters": [
      {
        "name": "桐藤渚 (Kirifuji Nagisa)",
        "role": "“茶会”主持人之一，菲利乌斯分派的领袖。",
        "appearance": "浅棕色长发，棕色眼瞳。头发上总是装饰着白色的百合花。气质高雅，脸上总是带着温柔的微笑，但这份从-容的背后似乎隐藏着深思熟虑的计谋。是三一优雅与礼仪的化身，非常喜欢喝红茶。"
      },
      {
        "name": "圣园未花 (Misono Mika)",
        "role": "“茶会”主持人之一，帕特尔分派的领袖。",
        "appearance": "粉色长发，金色眼瞳。性格开朗，像公主一样天真烂漫，但拥有超乎常人的恐怖力量，被戏称为‘三一的ゴリラ（大猩猩）’。是渚的青梅竹马。"
      },
      {
        "name": "百合园圣娅 (Yurizono Seia)",
        "role": "“茶会”主持人之一，圣父分派的领袖，拥有预知能力。",
        "appearance": "金色长发，粉红色眼瞳，拥有一对狐狸般的耳朵。身体病弱，总是带着一副慵懒、没睡醒的样子。拥有预知未来的能力，但这份能力也给她带来了沉重的负担。"
      }
    ],
    "environment": {
      "physical": "一个修剪完美的欧式庭院，以优雅的白色凉亭为中心，配有精致的茶具和盛开的花圃。整体环境充满了古典、高雅与神圣的美感，是三一风格的极致体现。",
      "socialAtmosphere": "表面上氛围宁静、礼貌且充满茶香，但在优雅的言辞之下，是三大派系间激烈的政治博弈与暗流涌动的权力斗争，充满了优雅而紧张的对峙感。"
    }
  }
}

