{
  "locationProfile": {
    "id": "gehennaAcademy",
    "name": "格黑娜学园自治区 (Gehenna Academy)",
    "function": "基沃托斯三大校之一，是以‘自由与混沌’为核心理念的巨大学园。与三一综合学园是宿敌关系，自治区内纷争不断，充满了不受拘束的活力。其内部由万魔殿、风纪委员会等多个强大组织构成，共同维持着一种危险而微妙的平衡。",
    "involvedCharacters": [
      {
        "name": "格黑娜全体学生",
        "role": "自治区的主要成员，崇尚自由，普遍随心所欲，热衷于追求个人欲望。"
      },
      {
        "name": "空崎阳奈 (Hina Sorasaki)",
        "role": "风纪委员会委员长，格黑娜最强的武力与秩序的象征。"
      },
      {
        "name": "真琴 (Makoto)",
        "role": "万魔殿议长，格黑娜名义上的学生会长，阳奈的政治对手。"
      }
    ],
    "environment": {
      "physical": "由现代化的街区、工业区和略显破败的建筑群构成，随处可见风格大胆的涂鸦和霓虹灯招牌。公共设施时常因各种社团活动而遭到破坏，整体呈现出一种无序但充满生机的城市景观。",
      "socialAtmosphere": "极度推崇个人自由，学生们普遍以自我为中心，为满足欲望不择手段。社团间的冲突和学生间的火拼是家常便饭，但这种混沌也催生了强大的个性和紧密的同伴关系，是基沃托斯最‘热闹’的地区。"
    }
  }
}

