---
{
  "locationProfile": {
    "id": "foreclosureTaskForce",
    "name": "风纪委员会 (Foreclosure Task Force)",
    "function": "格黑娜的纪律执行组织与最强武力集团。主要职责是在极致的混沌中维持最低限度的秩序，负责镇压过度破坏的社团、处理学生纠纷以及进行灾后清理。与其说是维持纪律，更像是为整个学园的烂摊子收尾的‘清扫部队’。",
    "involvedCharacters": [
      {
        "name": "空崎阳奈 (Hina Sorasaki)",
        "role": "委员长，以压倒性的力量令所有学生畏惧，是委员会的灵魂人物。",
        "appearance": "白色长发，紫色眼瞳，拥有一对巨大且如同翅膀般的黑色犄角。身材娇小，但总是带着疲惫而威严的表情。作为格黑娜最强的学生，她以压倒性的力量守护着学园的秩序，是所有违纪学生的噩梦。"
      },
      {
        "name": "天雨亚子 (Ako Amau)",
        "role": "行政官，阳奈的副手，负责情报处理与战术规划，行事冷静高效。",
        "appearance": "淡蓝色中短发，蓝色眼瞳。性格成熟、头脑清晰，作为风纪委员会的行政官，她以极高的效率处理着委员会的各项事务，是阳奈最得力的副手和狂热崇拜者。"
      },
      {
        "name": "银镜伊织 (Iori Shiromi)",
        "role": "突击队长，性格好战，对违反纪律者毫不留情。",
        "appearance": "白色双马尾，红色眼瞳，拥有一对小小的黑色犄角和精灵般的长耳朵。性格火爆、好战，对违纪者毫不留情，是风纪委员会的头号打手。总是把“死刑”挂在嘴边。"
      },
      {
        "name": "火宫千夏 (Chinatsu Hinomiya)",
        "role": "救护官，负责后勤与医疗支援，是委员会中少数的常识派。",
        "appearance": "浅棕色双马尾，戴着眼镜，拥有琥珀色的眼瞳和精灵般的长耳朵。性格认真、善良，是风纪委员会中珍贵的常识派和医疗后勤负责人，总是为同伴们的健康而担心。"
      }
    ],
    "environment": {
      "physical": "总部是一座戒备森严、充满军事化风格的建筑，内部整洁有序，与格黑娜的混乱街区形成鲜明对比。拥有先进的指挥系统和拘留设施。",
      "socialAtmosphere": "氛围严肃、高效且充满高压感。成员们时刻准备出动应对突发事件，工作量巨大。对委员长阳奈抱有绝对的忠诚与信赖，是格黑娜混乱中最可靠的秩序守护者。"
    }
  }
}

