entries.content:
---
{
  "locationProfile": {
    "id": "pandemoniumSociety",
    "name": "万魔殿 (Pandemonium Society)",
    "function": "格黑娜学园名义上的学生会，负责学园的日常行政管理。然而，其主要精力往往放在策划针对宿敌三一的阴谋，以及与风纪委员会进行权力斗争上。由于议长的不着调和成员的摸鱼，行政效率极低。",
    "involvedCharacters": [
      {
        "name": "羽沼真琴 (Makoto Hanuma)",
        "role": "议长，充满野心但时常显得头脑简单，执着于打倒三一和阳奈。",
        "appearance": "银白色长发，冰蓝色眼瞳，拥有一对巨大的黑色犄角。总是戴着象征权力的巨大军帽。性格高傲、充满野心，但计划总是因为考虑不周而失败，是个充满威严但又很搞笑的议长。"
      },
      {
        "name": "丹花伊吹 (Ibuki Tange)",
        "role": "成员，天真烂漫的吉祥物般的存在，深受其他成员的喜爱。",
        "appearance": "金色双马尾，金色眼瞳，拥有一对几乎看不见的小红角。性格天真无邪，是万魔殿所有成员都宠爱的吉祥物般的存在。"
      },
      {
        "name": "枣伊吕波 (Iroha Natsume)",
        "role": "书记官，虽然职位重要，但本人只想准时下班，经常在坦克里偷懒睡觉。",
        "appearance": "紫红色中长发，蓝色眼瞳，拥有精灵般的长耳朵。脸上总是带着慵懒和怕麻烦的表情。作为书记官，却是个终极的“摸鱼”主义者，最大的爱好是在她的坦克‘虎式’里睡觉。"
      },
      {
        "name": "空井皋月 (Satsuki Sorai)",
        "role": "副议长，负责处理万魔殿的日常事务。",
        "appearance": "粉色中长发，红色眼瞳，拥有一对黑色的恶魔犄角。脸上总是带着妩媚的笑容，展现出小恶魔般的气质。作为副议长，她比议长真琴要可靠得多。"
      },
      {
        "name": "友成千秋 (Chiaki Tomonari)",
        "role": "情报部长，负责收集和整理信息。",
        "appearance": "深蓝色短发，红色眼瞳，拥有一对弯曲的黑角和精灵般的长耳朵。性格冷静，负责万魔殿的情报工作，是混乱的万魔殿中少数认真工作的成员之一。"
      }
    ],
    "environment": {
      "physical": "位于格黑娜中心地带的豪华议会大楼，内部装饰浮夸，充满了权威的象征物，但文件和杂物常常堆积如山，显得有些杂乱。",
      "socialAtmosphere": "表面上是格黑娜的权力中枢，实际内部充满了懒散、官僚和阴谋诡计的气息。除了少数时刻，大部分时间都处于一种“茶话会”式的悠闲（或摸鱼）状态，与风纪委员会的紧张感截然不同。"
    }
  }
}

