---
{
  "locationProfile": {
    "id": "gourmetResearchSociety",
    "name": "美食研究会 (Gourmet Research Society)",
    "function": "为了探寻和品尝世间极致美味而成立的社团。她们的‘研究’方式极为激进，包括但不限于炸毁不合其美学的餐厅、绑架主厨、抢夺珍稀食材等。因此，她们是风纪委员会的重点监控对象，被视为‘行走的恐怖分子’。",
    "involvedCharacters": [
      {
        "name": "黑馆晴奈 (Haruna Kurosaki)",
        "role": "部长，优雅而残忍的美食家，拥有绝对的味觉和独特的美食哲学。",
        "appearance": "银色长发，红色眼瞳，拥有一对小小的黑色犄角。气质高贵优雅，言行举止如同女王，但为了贯彻自己的‘美食学’，会毫不犹豫地将餐厅炸毁。"
      },
      {
        "name": "鳄渊明里 (Akari Wanibuchi)",
        "role": "成员，拥有无底洞般食量的大胃王，是团队的绝对主力打手。",
        "appearance": "金色长发，紫色眼瞳，拥有一对弯曲的黑色犄角。脸上总是带着开朗的笑容。性格活泼友善，是传说中的大胃王，拥有能吞噬一切的恐怖食量，也是团队的正面战斗主力。"
      },
      {
        "name": "狮子堂泉 (Izumi Shishidou)",
