{
  "locationProfile": {
    "id": "problemSolver68",
    "name": "便利屋68 (Problem Solver 68)",
    "function": "由社长亚瑠创立的法外事务所，宣称‘只要给钱什么都做’，立志成为帅气又冷酷的法外狂徒。业务范围从寻物、保镖到破坏活动无所不包。然而，由于成员的特性，她们的计划总是走向意想不到的喜剧结局。",
    "involvedCharacters": [
      {
        "name": "陆八魔亚瑠 (Aru Rikuhachima)",
        "role": "社长，努力扮演着冷酷反派，但本性善良且时常犯傻，是团队的搞笑核心。",
        "appearance": "粉色长发，粉色眼瞳，拥有一对巨大且带有金色装饰的黑色犄角。努力扮演着冷酷的‘社长’形象，但实际上是个善良、爱面子且时常会犯傻的‘残念系’反派。"
      },
      {
        "name": "浅黄无月 (Mutsuki Asagi)",
        "role": "行动队长，喜欢捉弄人的小恶魔，享受制造混乱的过程。",
        "appearance": "白色短发，粉色眼瞳，拥有一对小小的黑色犄角。脸上总是带着小恶魔般的 mischievous 笑容。性格随心所欲，以捉弄亚瑠和制造混乱为乐，是团队的行动队长。"
      },
      {
        "name": "鬼方佳代子 (Kayoko Onikata)",
        "role": "课长，团队中最具常识和责任感的人，负责收拾残局和踩刹车。",
        "appearance": "标志性的黑白鸳鸯发色，红色眼瞳。表情冷淡，气质成熟。性格沉稳，是便利屋68中唯一的常识派和刹车担当，总是在为其他成员惹出的麻烦而头疼和收拾残局。"
      },
      {
        "name": "伊草遥香 (Haruka Igusa)",
        "role": "专员，性格阴郁自卑但破坏力惊人，是团队的爆破专家。",
        "appearance": "深紫色杂乱短发，紫色眼瞳。拥有一对小小的犄角。性格极度阴郁、自卑，总是处于恐慌状态，但她对亚瑠的崇拜是真诚的。虽然看起来很弱小，但一旦失控就会爆发出惊人的破坏力。"
      }
    ],
    "environment": {
      "physical": "在格黑娜自治区租用的一间小型事务所，内部被社长亚瑠努力装饰成‘硬汉派侦探事务所’的风格，但总是因各种意外而变得乱七八糟。",
      "socialAtmosphere": "一个充满奇妙家庭氛围的团队。尽管目标是成为法外狂徒，但成员间的羁绊非常深厚。充满了亚瑠的空想、无月的戏弄、佳代子的无奈和遥香的恐慌，混乱但异常温暖。"
    }
  }
}

