{
  "locationProfile": {
    "id": "hotSpringsDevelopmentDepartment",
    "name": "温泉开发部 (Hot Springs Development Department)",
    "function": "一个为了‘在任何地方都能挖出温泉’这一崇高（？）目标而成立的狂热技术社团。她们坚信只要钻探得足够深，任何地方都能涌出温泉。为此，她们不惜动用重型钻探设备，在格黑娜乃至基沃托斯各处进行无差别钻探，是造成大规模财产损失的惯犯。",
    "involvedCharacters": [
      {
        "name": "鬼怒川霞 (Kasumi Kinugawa)",
        "role": "部长，温泉开发的狂热信徒与理论家，拥有丰富的（歪门邪道）地质学知识。",
        "appearance": "棕黑色长发扎成两个独特的环形发髻，金色眼瞳，头戴一对小小的犄角。脸上总是带着从容而狡黠的微笑。性格懒散但头脑精明，是温泉开发理论的狂热信徒，擅长用各种歪理说服别人，让她们的破坏行为“合理化”。"
      },
      {
        "name": "下仓惠 (Meguri Shimokura)",
        "role": "成员，性格天然、充满活力的行动派，是社团的主要劳动力。",
        "appearance": "杂乱的红发上戴着标志性的护目镜，蓝绿色的眼瞳。拥有一对小小的黑色犄角和精灵般的长耳朵，脸上总是沾着一些机油污渍。性格活泼开朗、精力充沛，是纯粹的行动派，享受着挖掘作业带来的乐趣。"
      }
    ],
    "environment": {
      "physical": "没有固定的活动室，她们的‘据点’就是她们的巨型钻探载具‘温泉挖掘机’。她们神出鬼没，上一秒可能还在格黑娜的操场，下一秒就可能出现在千年科学学园的广场中央进行钻探作业。",
      "socialAtmosphere": "一个目标驱动、充满工匠精神（？）的偏执团体。成员们对温泉抱有纯粹而狂热的爱，为了实现目标可以无视一切规则和后果。她们的行为虽然极具破坏性，但本人却毫无恶意，单纯地为每一次（可能引发灾难的）温泉涌出而欢呼。"
    }
  }
}

