  "locationProfile": {
    "id": "millenniumScienceSchool",
    "name": "千年科学学园",
    "function": "基沃托斯最顶尖的理工科学院，以超前的科技和庞大的预算闻名。自治区本身就是一座未来主义的超巨大都市，是所有技术为核心的社团的聚集地，引领着整个基沃托斯的科技发展方向。",
    "involvedCharacters": [
      {
        "name": "调月莉音 (Rio Tsukatsuki)",
        "role": "前学生会长，理性的天才，千年问题的根源之一。"
      },
      {
        "name": "明星日鞠(Akeboshi Himari)",
        "role": "超天才清纯系病弱黑客，维里塔斯部长，拥有强大的情报能力，千年幕后的重要人物。"
      },
      {
        "name": "全体千年学生",
        "role": "普遍崇尚理性与效率，对科学技术有着极高的热情。"
      }
    ],
    "environment": {
      "physical": "由浮空岛、全息投影广告牌、精密几何建筑和高速轨道交通构成的未来都市。城区干净、整洁且高度自动化，充满了科技美感。其地下深处还埋藏着古代文明的超技术遗迹「Eridu」。",
      "socialAtmosphere": "技术竞赛和学术辩论是日常，但这种环境也常常因各种“失控的发明”或“预算超支”而陷入独特的混乱与喜剧之中。"
    }
