{
  "locationProfile": {
    "id": "seminar",
    "name": "研讨会 (Seminar)",
    "function": "千年的学生会，负责整个学园都市的行政管理、财政预算审批和日常运营。作为千年的大脑中枢，其最重要的工作就是管理那天文数字般的预算，并为其他社团的“破坏性行为”收拾残局。",
    "involvedCharacters": [
      {
        "name": "早濑优香 (Yuuka Hayase)",
        "role": "会计，以其无懈可击的计算能力管理着千年的财政，被誉为“研讨会的最终兵器”。",
        "appearance": "深蓝色长发扎成双马尾，紫色眼瞳。性格极其认真负责，对数字和规则一丝不苟，是研讨会里最可靠的常识派，每天都在为赤字和麻烦制造者们头疼。因其使用重型盾牌和结实的大腿，被学生们私下戏称为‘100公斤’。"
      },
      {
        "name": "生盐诺亚 (Noa Ushio)",
        "role": "书记，拥有过目不忘的超强记忆力，负责记录一切会议与事件，优香的亲密同事。",
