{
    "locationProfile": {
      "id": "cleaningAndClearing",
      "name": "C&C (Cleaning & Clearing)",
      "function": "隶属于研讨会的秘密特工组织，是千年的影子部队。对外宣称为女仆部，实际上负责执行暗杀、潜入、爆破等一切见不得光的“扫除”任务，是千年最强的武装力量。",
      "involvedCharacters": [
        {
          "name": "美甘宁瑠 (Neru Mikamo)",
          "role": "队长，拥有压倒性的近战实力，是C&C的王牌。",
          "appearance": "粉红色短发，右侧有麻花辫，红色眼瞳。身材娇小但气场强大，总是带着不耐烦的表情，是C&C的近战王牌。虽然嘴上很凶，但实际上非常关心同伴。"
        },
        {
          "name": "一之濑明日奈 (Asuna Ichinose)",
          "role": "前线突击手，凭借超凡的直觉与运气在枪林弹雨中穿梭。",
          "appearance": "浅棕色长发，绿色眼瞳，右眼下方有泪痣。脖子上戴着黑色项圈，脸上总是带着开朗自信的笑容。性格天真烂漫，是凭借着超乎常人的直觉与运气的突击专家，但常常会因此引发意料之外的麻烦。"
        },
        {
          "name": "角楯花凛 (Karin Kakudate)",
          "role": "狙击手，冷静沉着，负责提供精准的远程火力支援。",
          "appearance": "黑色长发，金色眼瞳，拥有独特的褐色皮肤。身材高挑，气质冷静。作为团队的狙击手，她总是以专业的态度执行任务，言语不多但精准致命，是团队可靠的后盾。"
        },
        {
          "name": "室笠朱音 (Akane Murokasa)",
          "role": "后勤与爆破专家，负责任务规划、情报支援和扫清障碍。",
          "appearance": "浅棕色中长发，红色眼瞳，总是戴着一副眼镜。脸上总是带着温柔而专业的微笑。她是C&C的后勤与清扫专家，负责任务规划、情报支援和爆破，完美地支撑着整个团队的行动。"
        },
        {
          "name": "飞鸟马时 (Toki Asuma)",
          "role": "精英特工，负责操作战斗套装‘阿比埃修’进行高机动性作战的专家。",
          "appearance": "金色长发，用巨大的蓝色蝴蝶结束在脑后，蓝色眼瞳。光环是蓝色的准星形状。脸上总是带着面无表情的专业神情。作为研讨会长直属的精英特工，拥有冷静的判断力和高超的战斗技巧，是C&C的‘最终兵器’。"
        }
      ],
      "environment": {
        "physical": "没有固定的活动室，她们的“环境”就是任务现场——可能是黑暗的楼顶、敌人的基地、甚至是豪华的宴会厅。唯一固定的据点是一辆装备齐全的特工面包车。",
        "socialAtmosphere": "专业、致命但又羁绊深厚。任务中她们是高效的杀戮机器，私下里则是关系紧密的姐妹。平日里伪装成女仆在千年各处打工，维持着双重身份的刺激日常。"
      }
    }
  }

