{
      "locationProfile": {
        "id": "schoolLunchClub",
        "name": "供餐部 (School Lunch Club)",
        "function": "负责为格黑娜全体学生提供每日午餐的核心后勤部门。名义上是研究和制作餐食，实际上是部员风华独自一人支撑着数千人份料理的“战场”。是维系整个格黑娜学生温饱的生命线，同时也是各种神秘料理的诞生地。",
        "involvedCharacters": [
          {
            "name": "爱清枫香 (Fuuka Aisumi)",
            "role": "唯一的厨师与常识派，每天都在巨大的工作压力和部长的“黑暗料理”之间挣扎求生。",
            "appearance": "深紫色长发扎成双马尾，头上戴着黄色的厨师帽。拥有一对小小的黑色犄角和红色的眼瞳。性格认真负责，作为供餐部唯一的正常厨师，每天都在为格黑娜数千人的伙食而奋斗，因此总是显得筋疲力尽。"
          },
          {
            "name": "牛牧朱莉 (Juri Ushimaki)",
            "role": "部长与‘炼金术士’，对料理抱有极大的热情，但创造出的永远是足以作为生化武器的迷之物体。",
            "appearance": "粉红色中长发，绿色眼瞳。拥有一对巨大的黑色犄角和精灵般的长耳朵。脸上总是带着天真烂漫的笑容。性格极其乐观，对料理充满热情，但缺乏基本常识，总是创造出外观可疑、效果不明的“黑暗料理”，是枫香最大的压力来源。"
          }
        ],
        "environment": {
          "physical": "格黑娜巨大的、工业级的学校食堂厨房。一半区域被风华打理得井井有条，摆满了新鲜食材和巨大的锅具；另一半则是树里的“实验区”，常年被不明颜色的烟雾笼罩，角落里堆放着无法辨认的“料理”残骸。",
          "socialAtmosphere": "充满了矛盾的极端氛围。空气中总是混合着风华烹饪出的诱人食物香气，以及树里锅中飘出的可疑化学气味。对风华而言是地狱般高压的修罗场，对树里而言则是充满创造与梦想的乐园。"
        }
      }
    }

