{
    "locationProfile": {
      "id": "veritas",
      "name": "真理部, 维里塔斯 (Veritas)",
      "function": "追求“真相”的天才黑客社团。她们是信息战的专家，能够侵入基沃托斯几乎所有的网络系统。社团活动内容包括揭露阴谋、寻找失落的技术以及偶尔因好奇心而引发大规模网络混乱。",
      "involvedCharacters": [
        {
          "name": "明星日鞠 (Himari Akeboshi)",
          "role": "部长，自称‘超天才清纯系病弱黑客’。维里塔斯的首任部长与绝对核心，拥有基沃托斯最顶级的黑客技术。因身体病弱而无法出门，总是通过网络远程指挥。",
          "appearance": "白发紫瞳，拥有精灵般的长耳朵。因身体孱弱需要依靠轮椅活动。总是带着自信满满的笑容，但这份从容背后似乎隐藏着不为人知的秘密。性格自恋、毒舌，但作为黑客的实力是顶尖的，在关键时刻极为可靠。"
        },
        {
          "name": "音兰千寻 (Chihiro Onlan)",
          "role": "副部长，理性的指挥者，负责在其他成员失控时踩下刹车。",
          "appearance": "黑色短发，绿色眼瞳。戴着一副绿色框架的眼镜，右侧刘海处有一个黄色的环形发卡。气质冷静沉着，是维里塔斯中为数不多的常识派和战术指挥官。拥有出色的判断力和领导力，在日鞠缺席或其他人失控时负责掌控局面。"
        },
        {
          "name": "小钩晴 (Hare Koguro)",
          "role": "工程与机械专家，能够制作各种黑客工具和电子设备。",
          "appearance": "银白色长发扎成高马尾，绿色眼瞳，刘海处有一个黑色的X形发卡。身穿深色连帽外套。总是一副慵懒、没干劲的样子，但拥有极高的技术力，能轻松制作出各种超出常识的电子设备。"
        },
        {
          "name": "小涂真纪 (Maki Konuri)",
          "role": "艺术与爆破担当，热爱涂鸦和一切能发出巨响的东西。",
          "appearance": "红色头发扎成两个俏皮的丸子头，蓝色眼瞳。性格活泼好动，充满艺术家的气质，热衷于在各种地方进行涂鸦创作。同时她对“BOMB”有着独特的痴迷，认为爆破也是一种艺术。"
        },
        {
          "name": "乙花小玉 (Kotama Othana)",
          "role": "通讯与窃听专家，热衷于收集和分析他人的秘密通讯。",
          "appearance": "米金色中长发，紫色眼瞳，戴着一副黑色圆框眼镜，刘海处有一个黑色的X形发卡。性格文静，不善言辞，但拥有超凡的听力。作为通讯与窃听专家，她能够捕捉到任何加密通讯，并热衷于分析其中蕴含的“八卦”。"
        }
      ],
      "environment": {
