{
    "locationProfile": {
      "id": "gameDevelopmentDepartment",
      "name": "游戏开发部 (Game Development Department)",
      "function": "以“制作出传说中的神作游戏”为目标的社团，但实际上大部分时间都在打游戏、看漫画和虚度光陰。尽管如此，成员们仍然怀揣着对游戏的热爱与梦想，并在关键时刻爆发出惊人的潜力。",
      "involvedCharacters": [
        {
          "name": "才羽桃井 (Momoi Saiba)",
          "role": "剧本与宣传担当，活泼开朗，是团队的元气制造者。",
          "appearance": "粉色短发，粉色眼睛，戴着一个像素风的猫咪发卡。性格外向、活泼好动，总是充满活力。作为游戏开发部的气氛制造者，她对游戏的热情能感染身边的每一个人。"
        },
        {
          "name": "才羽绿 (Midori Saiba)",
          "role": "美术担当，桃井的双胞胎妹妹，性格较为文静，负责游戏的原画与设计。",
          "appearance": "绿色长发，绿色眼睛，戴着与桃井同款的像素风猫咪发卡。性格内向、文静，与活泼的姐姐形成鲜明对比。她是一位才华横溢的画师，默默地用画笔支撑着游戏开发部的梦想。"
        },
        {
          "name": "花冈柚子 (Yuzu Hanaoka)",
          "role": "部长与程序担当，极度怕生的社交恐惧症患者，常年躲在活动室的储物柜里。",
          "appearance": "橘红色长发，常常因为害羞而满脸通红。由于极度的社交恐惧，她将活动室的储物柜改造成了自己的专属空间，吃住都在里面。虽然不善与人交流，但她是一位技术高超的程序员，也是游戏开发部真正的核心。"
        },
        {
          "name": "天童爱丽丝 (Aris Tendou)",
          "role": "身份不明的“勇者”，在废墟中被发现的神秘少女，将一切都用游戏术语来理解。",
          "appearance": "黑色超长发，蓝色眼瞳中有十字星图案。光环是一个奇特的钥匙形状。在废墟中被游戏开发部成员发现，失去了记忆。她坚信自己是游戏中的“勇者”，习惯用RPG术语来对话，天真烂漫，拥有远超常人的身体能力。"
        }

      ],
      "environment": {
        "physical": "一间被废弃的教室改造的活动室，里面堆满了各种游戏机、卡带、漫画、手办和零食。房间中央的大屏幕是她们娱乐和（偶尔）工作的核心。整体氛围舒适、杂乱但充满生活气息。",
        "socialAtmosphere": "轻松、悠闲、充满欢声笑语的“废部”氛围。这里是千年高压环境下的一片绿洲，成员们如同家人般亲密无间。虽然总是被废部危机困扰，但她们对游戏的热爱和彼此的友情是克服一切困难的动力。"
      }
    }
  }

