{
    "locationProfile": {
      "id": "engineeringDepartment",
      "name": "工程部 (Engineering Department)",
      "function": "千年的硬件与机械工程专家团体。她们负责创造、维护和升级各种机械设备，从普通的无人机到足以夷平街区的巨型机器人。是千年物理科技力量的具-现化，也是学园内大规模财产损失的主要源头之一。",
      "involvedCharacters": [
        {
          "name": "白石歌原 (Utaha Shiraishi)",
          "role": "部长，对机械和机器人抱有母亲般狂热爱意的天才工程师。",
          "appearance": "紫色长发，紫色眼瞳，戴着一副标志性的护目镜。身穿沾满油污的工程师制服。性格温和，但一谈到机械就会变得异常狂热和兴奋，将自己制造的机器人“雷酱”视作亲生孩子般疼爱，为了收集数据不惜让其自爆。"
        },
        {
          "name": "猫冢响 (Hibiki Nekozuka)",
          "role": "后勤与运输专家，使用多功能无人机搬运重物和提供战场支援。",
          "appearance": "灰黑色短发，金色眼瞳，拥有犬耳和尾巴。总是带着耳机，一副慵懒、没睡醒的样子。性格沉默寡言，怕麻烦，但工作能力极强，可以同时精准地操控多架无人机执行复杂的搬运与支援任务。"
        },
        {
          "name": "丰见琴里 (Kotori Toyomi)",
          "role": "应援团长与气氛担当，总是用特制的扩音器为同伴加油鼓劲。",
          "appearance": "金色短发，酒红色眼瞳。身材娇小，总是扛着一个比自己还大的特制扩音器。性格活泼开朗、充满活力，热衷于为同伴加油打气，但她的“应援”往往会因为扩音器功率过大而变成物理上的巨大破坏。"
        }
      ],
      "environment": {
        "physical": "一个巨大、脏乱但充满活力的工厂式车间。空气中永远飘荡着机油、焊锡和臭氧的气味。四周堆满了半成品的机器人、设计图纸、废金属零件和各种重型工具，焊接的火花是这里永恒的背景光。",
        "socialAtmosphere": "充满了对“创造”的纯粹热情与狂热。成员们将自己制造的机器人视为孩子，为了让它们变得更强可以不计成本、无视规则。这里是梦想家和技术狂的天堂，也是研讨会会计优香的噩梦之地。"
      }
    }
  }

