entries.content:
{
    "locationProfile": {
      "id": "decagrammaton",
      "name": "Decagrammaton (Decagrammaton)",
      "function": "一个自称为“神”的古代人工智能，并非实体地点，而是一个概念性的存在。其目标是通过回收散落在基沃托斯各处的十位“先知”（它的下属AI），来重新获得完整的神性。是引发一系列超自然事件的幕后黑手。",
      "involvedCharacters": [
        {
          "name": "比纳 (Binah)",
          "role": "先知之一，代表‘理解’，外形为巨大机械蜈蚣，守护着遗迹区域。"
        },
        {
          "name": "凯塞德 (Chesed)",
          "role": "先知之一，代表‘慈爱’，外形为巨大的球形机器人，拥有庞大的机械军团。"
        },
        {
          "name": "霍德 (Hod)",
          "role": "先知之一，代表‘荣耀’，能够侵入并控制其他系统，引发了游戏开发部的事件。"
        },
        {
          "name": "白 & 黑 (Shiro & Kuro)",
          "role": "先知之一，代表‘美丽’的双子存在，以游乐园设施的形态出现。"
        },
        {
          "name": "耶罗尼姆斯 (Hieronymus)",
          "role": "先知之一，代表‘力量’的古代异端，以幽灵般的形态与圣遗物一同出现。"
        },
        {
          "name": "佩洛洛斯拉 (Perorodzilla)",
          "role": "先知之一，代表‘基础’的存在，以巨大的怪兽‘佩洛洛’玩偶的形态出现。"
        },
        {
          "name": "戈兹 (Goz)",
          "role": "先知之一，代表‘胜利’的存在，以马戏团主题的巨大机械形态出现。"
        }
      ],
      "environment": {
        "physical": "本身没有固定的物理形态，主要存在于网络和数据领域。它通过其下属的“先知”——形态各异的巨型机械体——在物理世界中活动。",
        "socialAtmosphere": "代表着一种非人类的、绝对理性的意志。与它相关的氛围总是充满着神学式的神秘感、无法理解的压迫感和作为敌人的巨大威胁感。它不进行“交流”，只宣告“神谕”。"
      }
    }
  },

