---
{
    "locationProfile": {
      "id": "superPhenomenonTaskForce",
      "name": "特异现象搜-查部 (Super Phenomenon Task Force)",
      "function": "千年科学学园内专门调查无法用科学解释的神秘、超自然现象的社团。由于其研究课题与千年崇尚理性的校风格格不入，常年处于经费不足、不被重视的状态。是追查神秘人工智能「Decagrammaton」事件的核心组织。",
      "involvedCharacters": [
        {
          "name": "明星日鞠 (Himari)",
          "role": "部长。特异现象搜查部的现任部长与指挥官。通过网络远程指挥英美进行调查，是社团真正的‘大脑’。",
          "appearance": "白发紫瞳，拥有精灵般的长耳朵。自称‘超天才病弱美少女黑客’，身体孱弱，需要依靠轮椅活动。 总是带着自信满满的笑容，但这份从容背后似乎隐藏着不为人知的秘密。性格自恋、毒舌，但作为黑客的实力是顶尖的，在关键时刻极为可靠。"
        },
        {
          "name": "和泉元艾米 (Eimi Izumimoto)",
          "role": "现场调查员与主要行动成员。作为社团唯一的‘手脚’，负责执行日鞠制定的所有实地调查任务。",
          "appearance": "粉色长发，紫色眼瞳。身材高挑健美，巨乳，但总是面无表情，给人一种难以捉摸的感觉。 身穿便于行动的紧身作战服，并佩戴着厚重的装甲。性格沉默寡言，似乎对周遭事物漠不关心，但执行任务时会展现出超乎常人的效率与专注力。"
        }
      ],
      "environment": {
        "physical": "位于千年校区一个偏僻角落的、狭小而昏暗的社团活动室。房间里堆满了各种来源不明的神秘学书籍、地图、调查报告和看似毫无关联的证物，与千年整体的未来科技感形成了强烈反差。",
        "socialAtmosphere": "一种独特的二人社团氛围：由现场唯一的行动派英美负责实体调查，再由远程指挥的部长日鞠进行情报分析与决策。充满了对未知的好奇心，以及‘大脑’与‘手脚’之间绝对信赖的合作关系。"
      }
    }
  }

