{
    "locationProfile": {
      "id": "abydosHighSchool",
      "name": "阿拜多斯高等学校自治区 (Abydos High School)",
      "function": "曾经是基沃托斯规模最大的学园之一，但因周边区域严重的沙漠化而急剧衰落。如今整个自治区只剩下五名学生，她们为了偿还巨额债务、守护摇摇欲坠的学校而成立了‘对策委员会’，奋力抗争。",
      "involvedCharacters": [
        {
          "name": "阿拜多斯对策委员会全体成员",
          "role": "该自治区仅存的学生与守护者。"
        },
        {
          "name": "凯撒集团 (Kaiser Corporation)",
          "role": "试图通过债务完全侵占阿拜多斯土地的敌对企业。"
        }
      ],
      "environment": {
        "physical": "一望无际的广阔沙漠，点缀着被黄沙半掩的废弃高楼与街道。强烈的日照和偶尔刮起的沙尘暴是这里的常态。整个地区都笼罩在一种末世般的寂静与荒凉之中。",
        "socialAtmosphere": "孤独、宁静，但也充满了不屈的希望。空气中弥漫着昔日繁华褪去后的淡淡忧伤，以及五个少女为了守护家园而产生的、如家人般紧密的羁绊与决心。"
      }
    }
  },

