    "locationProfile": {
      "id": "abandonedCommercialDistrict",
      "name": "废弃商业街 (Abandoned Commercial District)",
      "function": "阿拜多斯昔日繁华的中心，如今已是空无一人的废墟。这里是‘对策委员会’进行各种‘打工’活动（如抢劫凯撒信贷的银行）和与敌对势力交战的主要舞台。",
      "involvedCharacters": [
        {
          "name": "阿拜多斯对策委员会",
          "role": "主要活动者。"
        },
        {
          "name": "头盔团 (Helmet Gang)",
          "role": "盘踞于此的敌对混混团体。"
        },
        {
          "name": "凯撒集团的PMC部队",
          "role": "负责守护凯撒资产的敌对武装力量。"
        }
      ],
      "environment": {
        "physical": "被黄沙侵蚀的街道，两旁是门窗破损、招牌褪色的商店和银行。除了风声之外一片死寂，偶尔会有流弹划破空气，在废弃的建筑上留下新的弹痕。",
        "socialAtmosphere": "无法地带。充满了危险和一触即发的紧张感，是力量决定一切的地方。每一栋建筑背后都可能隐藏着敌人，是考验对策委员会战斗技巧与团队合作的试炼场。"
      }
    }
  }

