{
    "locationProfile": {
      "id": "onmyobu",
      "name": "阴阳部 (Onmyobu)",
      "function": "百鬼夜行的学生会，负责整个学园的行政管理、祭典审批和内外事务。在「百花缭乱」失踪后，她们成为了维持学园秩序的唯一核心。行事风格传统而保守，注重规矩与占卜。",
      "involvedCharacters": [
        {
          "name": "天地尼娅 (Niya Amachi)",
          "role": "代理会长，充满神秘感的阴阳部最高负责人。",
          "appearance": "黑色短发，金色眼瞳，头上有两个鬼一般的犄角，其中左边的角是断裂的。总是眯着眼睛，带着捉摸不透的微笑，偶尔会露出猫嘴。身穿袖子分离的和风服装，经常拿着一把折扇。性格慵懒、爱捉弄人，是个深不可测的策略家。"
        },
        {
          "name": "桑上佳穗 (Kaho Kuwakamu)",
          "role": "副会长，认真负责的常识派，承担了大部分实际工作。",
          "appearance": "金色长发，用发箍束起并扎成低马尾，琥珀色眼瞳和一对狐狸耳朵。身材高挑，气质成熟。身穿露出度较高的改良和服，总是带着严肃而可靠的表情，是阴阳部里珍贵的正常人。"
        },
        {
          "name": "和乐知世 (Chise Waraku)",
          "role": "部员，热爱俳句的神秘少女，拥有不可思议的运气。",
          "appearance": "浅蓝色长发，粉红色眼瞳，头上有两个小小的红色犄角，左侧头发上别着一朵巨大的白色花饰。气质独特，充满神秘感，在百鬼夜行极具人气。"
        }
      ],
      "environment": {
        "physical": "一处庄严、肃穆，如同神社般的主殿。内部装饰着古老的卷轴、符咒和巨大的算盘，充满了传统与神秘主义的气息。空气中飘散着淡淡的线香气味。",
        "socialAtmosphere": "氛围保守、严谨且略带神秘。成员们严格遵循着古老的规定行事，与百鬼夜行热闹的街区形成了鲜明对比。是学园内最注重规则与秩序的地方。"
      }
    }
  }

