{
    "locationProfile": {
      "id": "ninjutsuResearchDepartment",
      "name": "忍术研究部 (Ninjutsu Research Department)",
      "function": "以复兴并研究现代忍术为目标的社团。成员们以成为帅气的忍者为目标进行着各种修行，但她们的‘忍术’往往是融合了现代科技的、看起来有些滑稽的“魔术”。",
      "involvedCharacters": [
        {
          "name": "大野月咏 (Tsukuyo Oono)",
          "role": "成员。身材高大但性格胆小。",
          "appearance": "深紫色长发，总是遮住一只眼睛，拥有黑色的兽耳，瞳色为紫色。身穿忍者风格的制服，戴着紫色围巾。身材高大，但性格胆小，不是擅长跟别人说话的类型。"
        },
        {
          "name": "久田泉奈 (Izuna Kuda)",
          "role": "成员。对忍术修行抱有极致热忱的努力家，将老师视为自己侍奉的‘主君’。",
          "appearance": "黑色遮脸短发，金色眼瞳，拥有显眼的狐狸耳朵和巨大的狐狸尾巴。身穿融合了水手服元素的忍者服，披着一件粉色花纹的羽织，并围着一条长长的洋红色围巾。左耳边戴着狐狸面具发饰。性格极其认真、努力，为了成为顶级忍者而进行着严格的修行，并将老师尊称为‘主君’。"
        },
        {
          "name": "千鸟满 (Michiru Chidori)",
          "role": "部长。经常没什么依据但就是很自信满满的忍术研究部部长。",
          "appearance": "银灰色头发扎成两个像兽耳一样的发髻，金色眼瞳。喜欢电影、漫画、周边的忍者死宅，因此创立了「忍术研究部」，会在视频平台「少女忍法帖满酱」投稿视频。为了让整个基沃托斯知道忍者的优势，而进行视频投稿等，每天都和部员的大家一起奋斗！"
        }
      ],
      "environment": {
        "physical": "一间位于百鬼夜行角落的、看似普通的旧道场，但内部布满了各种失败的机关陷阱和忍术道具。墙上贴着“忍法帖”和各种修行计划。",
        "socialAtmosphere": "充满了轻松、搞笑和不着调的氛围。成员们都在非常认真地进行着她们自己所理解的“忍术修行”，这种认真与修行内容的滑稽形成了强烈的喜剧效果。"
      }
    }
  }

