{
  "locationProfile": {
    "id": "festivalOperationsCommittee",
    "name": "祭典运营委员会 (Festival Operations Committee)",
    "function": "负责策划和运营百鬼夜行联合学园内全年无休的各种祭典活动。从预算管理、摊位审批到安全保障，她们是确保庆典顺利进行的核心团队。",
    "involvedCharacters": [
      {
        "name": "河和静子 (Kawa Shizuko)",
        "role": "委员长，认真负责但总是为各种麻烦而头疼。",
        "appearance": "深棕色头发扎成两个环形，棕色眼瞳。总是穿着女仆装风格的制服。性格认真，责任心强，但因为各种突发状况而经常陷入恐慌，是委员会的操心担当。"
      },
      {
        "name": "白石海香 (Shiraishi Fubuki)",
        "role": "保安，名义上的秩序维护者，实际上是摸鱼惯犯。",
        "appearance": "灰绿色短发，拥有一对下垂的犬耳。脸上总是带着懒散的表情。性格极其怕麻烦，能坐着绝不站着，是委员会的“摸鱼”担当。"
      },
      {
        "name": "朝比奈菲娜 (Asahina Fina)",
        "role": "成员，充满活力的气氛制造者。",
        "appearance": "金色长发扎成高高的马尾，蓝色眼瞳。性格开朗活泼，是委员会的元气少女，总能用她的活力感染大家。"
      }
    ],
    "environment": {
      "physical": "一间总是堆满了祭典用品、宣传单和各种零食的活动室。室内总是乱糟糟的，充满了节庆前的忙碌与混乱气息。",
      "socialAtmosphere": "充满了活力的同时也伴随着无尽的混乱。在静子的努力和另外两名成员的“非协力”下，奇迹般地维持着运营。是百鬼夜行欢乐气氛的创造者，也是混乱的源头之一。"
    }
  }
}

