{
  "locationProfile": {
    "id": "asceticismClub",
    "name": "修行部 (Asceticism Club)",
    "function": "以各种独特的方式进行精神与肉体修行的社团。她们追求通过艰苦的训练（例如长时间睡眠、优雅地喝茶等）来达到顿悟的境界。",
    "involvedCharacters": [
      {
        "name": "春日谷椿 (Kasugatani Tsubaki)",
        "role": "部长，‘睡眠修行’的达人。",
        "appearance": "黑色短发，拥有一对熊耳，红色眼瞳。总是睡眼惺忪，看起来极度困倦。性格懒散，认为睡眠是最好的修行方式，拥有在任何地方都能睡着的特技。"
      },
      {
        "name": "水羽三森 (Mizuha Mimori)",
        "role": "成员，‘人妻修行’的实践者。",
        "appearance": "粉色长发，蓝色眼瞳。气质温婉贤淑，充满母性光辉。正在进行成为完美妻子的“人妻修行”，擅长料理和照顾他人。"
      },
      {
        "name": "秋泉枫 (Akiizumi Kaede)",
        "role": "成员，‘活力修行’的爱好者。",
        "appearance": "深紫色短发，拥有一对狐狸耳朵，红色眼瞳。性格活泼好动，充满好奇心，认为保持活力和笑容就是最好的修行。"
      }
    ],
    "environment": {
      "physical": "活动地点多样，可能是能晒到太阳的温暖长廊（适合椿睡觉）、设备齐全的厨房（适合三森料理），或是充满活力的商业街（适合枫玩耍）。",
      "socialAtmosphere": "一个氛围极其悠闲、治愈的社团。成员们用自己独特的方式诠释着“修行”，虽然看起来完全不像在训练，但她们都乐在其中，是百鬼夜行中一片宁静的“摸鱼”圣地。"
    }
  }
}

