{
  "locationProfile": {
    "id": "redWinterFederalAcademy",
    "name": "赤冬联邦学园 (Red Winter Federal Academy)",
    "function": "基沃托斯最北端的学园，坐落于广阔的冻土与雪山之上。校风极其保守、官僚，但内部所谓的“肃清”与“革命”等政治斗争，本质上都是围绕会长切里诺的奇思妙想展开的滑稽闹剧。",
    "involvedCharacters": [
      {
        "name": "赤冬全体学生 (All Red Winter Students)",
        "role": "构成了这个在冰天雪地中上演着荒诞喜剧的学园的全体人员，分属于赤冬事务所、227号特别班等多个组织。"
      }
    ],
    "environment": {
      "physical": "一个被冰雪覆盖的广阔自治区。建筑风格充满了厚重、威严的色彩，但许多设施因资源短缺而显得老旧。无尽的雪原是这里永恒的背景。",
      "socialAtmosphere": "充满了夸张的官僚主义和荒诞的政治戏剧感。学生们的生活围绕着朝令夕改的规定和突如其来的政治运动，但斗争的理由往往是为了零食、取暖之类的琐事，将严肃的口号用于最日常的欲望，充满了反差的喜剧效果。"
    }
  }
}

