{
  "locationProfile": {
    "id": "redWinterOffice",
    "name": "赤冬事务所 (Red Winter Office)",
    "function": "赤冬联邦学园的学生会与最高权力机构。名义上负责学园的行政管理，实际上是会长切里诺实现其各种异想天开的“独裁者游戏”的舞台。",
    "involvedCharacters": [
      {
        "name": "连河切里诺 (Cherino Renkawa)",
        "role": "会长",
        "appearance": "白色短发，蓝色眼瞳。身材娇小，但总是戴着一顶与身材不符的巨大军帽。性格极其自负，热衷于个人崇拜和发表各种宏大演说，但计划总是因考虑不周而失败，是个充满喜剧色彩的“胡闹独裁者”。"
      },
      {
        "name": "池仓玛丽娜 (Marina Ikekura)",
        "role": "保安委员长",
        "appearance": "金色波波头，红色眼瞳。表情严肃，是切里诺最忠诚的执行者。性格耿直，对会长切里诺哪怕最荒唐的命令也会毫不犹豫地严肃执行，是喜剧效果的主要放大器。"
      },
      {
        "name": "佐城巴 (Tomoe Sashiro)",
        "role": "事务局长",
        "appearance": "粉色长发，紫色眼瞳。气质沉稳。作为事务局长，她是混乱的事务所中唯一一个试图用常识去解决问题的“常识派”，每天都在为会长切里诺的各种奇思妙想收拾残局。"
      }
    ],
    "environment": {
      "physical": "一栋充满威严感的办公大楼，内部挂满了切里诺的肖像和各种宣传标语，文件堆积如山。",
      "socialAtmosphere": "充满了对会长切里诺的（表面）绝对忠诚和夸张的官僚主义气息。氛围看似严肃，但因为切里诺本人的不着调和大家心照不宣的“陪玩”心态而时常上演各种滑稽剧。"
    }
  }
}

