{
  "locationProfile": {
    "id": "specialClass227Barracks",
    "name": "第227号特别班驻地 (227th Special Class Barracks)",
    "function": "因各种鸡毛蒜皮的小事（比如打碎了会长的雕像）而被切里诺“肃清”的学生们组成的特殊班级。名义上是反省，实际上是摸鱼圣地。她们策划的所谓“革命”，其最终目的往往是为了夺回被没收的布丁或小说。",
    "involvedCharacters": [
      {
        "name": "天见和香 (Nodoka Amami)",
        "role": "狙击手兼观察员",
        "appearance": "粉色短发，红色眼瞳。性格温柔，但内心坚强。热衷于使用望远镜进行观察，是227号班的情报来源（比如监视食堂什么时候开饭）。"
      },
      {
        "name": "角楯时雨 (Shigure Kakudate)",
        "role": "后勤与载具驾驶员",
        "appearance": "浅蓝色短发，蓝色眼瞳，拥有一对犬科动物的耳朵。总是戴着防寒帽和耳机。性格慵懒，喜欢喝酒，是班级里可靠的驾驶员和物资（主要是零食和酒）管理者。"
      }
    ],
    "environment": {
      "physical": "位于赤冬边境冻土上的一个简陋露营地。由帐篷、篝火和一些老旧的设备组成，生活条件虽然艰苦，但充满了悠闲的气息。",
      "socialAtmosphere": "虽然名义上是被流放，但成员之间充满了家人般的信赖与温情，氛围极其悠闲。这里是远离切里诺官僚主义的“摸鱼天堂”，所谓的“斗争”也只是为了改善生活品质（比如喝上热饮）而进行的充满喜剧色彩的努力。"
    }
  }
}

