{
  "locationProfile": {
    "id": "redWinterWorksDepartment",
    "name": "工务部 (Works Department)",
    "function": "赤冬联邦学园的建设与工程部门。负责所有土木工程、基础设施建设和维护。虽然工作能力出色，但部长实梨是一位狂热的劳工权益倡导者，会因为微不足道的小事（比如要求更多布丁，要求每周休息4天）而组织全体成员进行罢工和示威，是让赤冬事务所头疼不已的‘罢工惯犯’。",
    "involvedCharacters": [
      {
        "name": "安守实梨 (Minori Yasumori)",
        "role": "部长，狂热的劳工权益活动家。",
        "appearance": "灰色短发，蓝绿色眼瞳。总是戴着一顶白色安全帽，身穿厚重的防寒工作服。性格充满激情，工作能力很强，但会将全部热情投入到为部员争取权利的罢工和示威活动中，是个精力充沛的麻烦制造者。"
      }
    ],
    "environment": {
      "physical": "没有固定的办公室，她们的据点就是赤冬境内各个尘土飞扬（或者说雪花飞扬）的建筑工地。四周总是围绕着重型机械、建筑材料和各种抗议标语牌。",
      "socialAtmosphere": "充满了劳动号子声和抗议口号声的奇特氛围。成员们在实梨的带领下，一方面是勤劳的建设者，另一方面又是随时准备罢工的‘革命家’。这里是整个赤冬最‘吵闹’的地方之一。"
    }
  }
}

