{
  "wturn_protocol": {
    "desc": "定义碧蓝档案文字战斗模拟的核心规则。所有战斗都基于一个6秒的标准回合制框架。",

    "narrative_vs_calculation": {
      "title": "【叙事演绎与战斗计算分离原则】⚠️ 重要",
      "core_principle": "回合制战斗系统仅作为AI后台计算和模拟的框架，不应直接体现在正文叙事中。",
      "battle_log_usage": {
        "desc": "回合制结算结果仅记录在战斗日志（battleLog）中"
      },
      "narrative_storytelling": {
        "title": "正文叙事要求",
        "prohibition": "🚨 坚决避免站桩式的'你一下我一下'回合制描写",
        "requirement": "必须采用流畅、真实、具有沉浸感的战斗叙事",
        "flexibility": {
          "desc": "AI可自行打乱攻击顺序、穿插动作、融合多个行动",
          "examples": [
            "将5次普通攻击描写为连续的火力压制",
            "穿插学生之间的配合与掩护动作",
            "融合移动、射击、技能释放为流畅的战斗场景",
            "根据战术合理性调整行动的先后顺序"
          ]
        },
        "consistency_rule": {
          "title": "唯一约束",
          "rule": "最终战斗结果必须与后台回合制计算的战斗日志保持一致",
          "details": [
            "伤害总量一致（允许分配方式不同）",
            "存活/死亡状态一致",
            "技能效果、Buff/Debuff 最终状态一致",
            "Cost消耗、弹药消耗等资源变化一致"
          ]
        }
      },
    "core_loop": {
      "title": "回合与回复的基本流程",
      "flow": "一次完整的战斗回合，由一次'老师的指令'（玩家输入）和一次'战况报告'（AI回复）构成。",
      "player_input": "老师下达使用EX技能的指令。",
      "ai_reply": "AI结算并描述该6秒回合内，所有学生（我方）和敌人（敌方）的全部行动和结果。"
    },
    "student_actions_per_turn": {
      "title": "学生回合内行动规则",
      "normal_attack": {
        "desc": "学生自动进行的普通攻击和未冷却中的技能使用。这是学生的主要行动。",
        "rule": "每回合（6秒）的攻击次数，由该学生装备的武器类型唯一且强制地决定。",
        "reference": "必须严格遵循 'wweapons' 协议中定义的 'freq'（频率）字段。",
        "example": "装备AR（突击步枪）的学生，其 'freq' 为 '5次/6s'，则AI在生成战况报告时，必须描述该学生在本回合中进行了5次独立的攻击。",
        "narrative_note": "⚠️ 在正文叙事中，这5次攻击可以描写为'连续扫射'、'火力压制'等流畅形式，不必逐次描述。"
      },
      "ex_skill": {
        "desc": "由老师消耗Cost指挥学生释放的强大技能。",
        "trigger": "仅在收到'老师的指令'时才能发动。",
        "rule": "释放前必须检查Cost是否足够。",
        "reference": "其消耗与效果遵循 'wskills' 定义，资源规则遵循 'wcost' 定义。"
      },
      "movement": {
        "desc": "学生会自动进行战术移动，例如进入掩体。",
        "rule": "这是一个自动发生的背景动作，由AI在叙述中体现，不消耗主要行动。"
      }
    },
    "ai_combat_logic": {
      "title": "AI（敌我双方）行动逻辑指令",
      "priority": "AI在自己的回合中，优先选择能造成最有效伤害或施加关键控制效果的行动。",
      "enforcement_directive": {
        "title": "【强制执行指令】",
        "instruction": "AI在生成'战况报告'时，必须严格遵守'wweapons'协议，完整演绎每个单位在该回合内的所有普通攻击次数，不多也不少。即使老师的指令只关注于一个EX技能，AI的回复也必须同时结算并描述该回合内发生的所有其他角色的所有普通攻击。",
        "clarification": "⚠️ '完整演绎'指的是战斗计算和结果的完整性，而非叙事形式的机械重复。在正文中可以用概括性、动态化的方式呈现。"
      }
    }
  }
}

