---
{
      "name_cn": "比纳",
      "name_jp": "Binah",
      "series": "十字神名",
      "appearance": "一条巨大无比的、在沙海中移动的机械蜈蚣或长蛇。它的身体由无数厚重的装甲节片构成，头部是巨大的钻头和感应器，充满了古代超文明的战争兵器风格，压迫感极强。",
      "background": "“十字神名”序列第三位的预言者，首次在阿拜多斯的沙漠地区被发现。其出现在此地的原因尚不明确，但它拥有的恐怖破坏力使其成为必须被排除的危险存在。",
      "attributes": {
        "armor_type": "重装甲",
        "attack_type": "贯通",
        "location": "市街/室外"
      },
      "combat_flow": {
        "summary": "一个考验队伍控制能力(CC)和持续输出能力的Boss。战斗分为三个阶段，Boss会随着血量降低而变得更加危险。",
        "phases": [
          {
            "phase_number": 1,
            "trigger": "战斗开始 (高生命值阶段)",
            "description": "Boss使用常规技能攻击，ATG累积满后会释放大范围高伤害技能'净化风暴'。",
            "mechanics": ["主要技能包括'A-h.a 导弹'和'正义之祸'。"]
          },
          {
            "phase_number": 2,
            "trigger": "HP降低到中等水平",
            "description": "行动模式基本不变，但会增加一项机制：钻入地下，然后从场地另一端钻出，强制我方队伍重新部署。",
            "mechanics": ["钻地移动会打乱我方阵型。"]
          },
          {
            "phase_number": 3,
            "trigger": "HP降低到低水平",
            "description": "Boss的ATG累积速度显著加快，'净化风暴'的释放频率变得更高。",
            "mechanics": ["攻击更具侵略性，对队伍的生存和控制链是巨大考验。"]
          }
        ],
        "groggy_condition": "主要通过对我方单位施加的'减益效果'和我方对Boss施加的'控制效果'（CC）来累积无力值。"
      }
    }

