entries.content:
{
  "name_cn": "猫鬼・黒影",
  "name_jp": "Kurokage",
  "series": "幻魑百物语",
  "appearance": "一只巨大的、由怨念集合而成的黑色猫状怪物，身体呈现半透明的黑影形态，带有紫色的能量纹路和不祥的鬼火光芒。它的周围常常伴随着数只体型较小的、同样是幽灵形态的“猫鬼”。",
  "background": "在百鬼夜行流传的怪谈“幻魑百物语”中出现的神秘构造物。其真实身份不明，以破坏祭典为乐的同时，似乎也在寻找着什么。",
  "attributes": {
    "armor_type": "弹力装甲",
    "attack_type": "神秘",
    "location": "市街"
  },
  "combat_flow": {
    "summary": "战斗核心是处理召唤物'猫鬼'，并通过控制它们来使Boss本体进入虚弱状态。",
    "phases": [
      {
        "phase_number": 1,
        "trigger": "战斗开始",
        "description": "Boss与数个'猫鬼'小怪同时在场进行攻击。",
        "mechanics": ["Boss会使用'猫鬼的咆哮'、'呼唤化身的鬼哭'等范围技能。", "'猫鬼'小怪会持续攻击我方单位。"]
      },
      {
        "phase_number": 2,
        "trigger": "Boss HP < 75%",
        "description": "Boss展开'猫鬼的领域'，将战场转移至一个只有它和ATG（无力值槽）的特殊空间，Boss本体此时无法被攻击。",
        "mechanics": ["在此阶段，Boss会持续召唤'猫鬼'小怪。", "玩家必须对场上的'猫鬼'施加控制效果（如眩晕、恐惧等）才能填充无力值槽。"]
      },
      {
        "phase_number": 3,
        "trigger": "无力值槽填满后，脱离'猫鬼的领域'，返回原战场。",
        "description": "Boss进入虚弱状态，战斗模式与第一阶段相似，但技能可能得到强化。",
        "mechanics": ["Boss在虚弱期间受到伤害增加。", "继续召唤'猫鬼'小怪进行攻击。"]
      }
    ],
    "groggy_condition": "在第二阶段，通过对'猫鬼'施加控制效果来填充无力值槽。"
  }
}

