entries.content:
{
  "name_cn": "格里高利",
  "name_jp": "Gregorius",
  "appearance": "一位身着华丽而诡异的暗色主教长袍的人形生物。它的面部被完全遮挡，背后有一个巨大、扭曲的金色光环结构，整体设计风格充满了堕落与异端化的宗教色彩，散发着令人不安的神圣感。",
  "background": "在圣三一地下发现的古代圣堂中的“伪圣者”，是一个异端派系的领袖。其言行和外表都透露出与现有圣三一学生截然不同的诡异风格。",
  "attributes": {
    "armor_type": "轻装甲",
    "attack_type": "神秘",
    "location": "室内"
  },
  "combat_flow": {
    "summary": "核心机制是通过击败召唤物'唱诗班'来推进阶段，并在特定条件下应对其终极技能。",
    "phases": [
      {
        "phase_number": 1,
        "trigger": "战斗开始",
        "description": "此阶段分为三个小阶段。Boss会使用除终极技能外的所有技能。",
        "mechanics": ["每个小阶段开始时，Boss会召唤2个'唱诗班'。", "必须击败所有'唱诗班'，才能结束当前小阶段并进入下一个。", "完成所有三个小阶段后，进入第二阶段。"]
      },
      {
        "phase_number": 2,
        "trigger": "完成第一阶段的所有小阶段",
        "description": "Boss开始准备并使用其毁灭性的终极技能'普世之救赎'。",
        "mechanics": ["Boss会持续进行范围攻击。", "特殊机制：当战斗剩余时间不足40秒，且Boss已释放过3次'肃穆之悔悟'技能后，它必定会释放'普世之救赎'。"]
      }
    ],
    "groggy_condition": "无常规累积方式。其核心弱点在于，当它准备释放终极技能'普世之救赎'时，会有一个短暂的虚弱窗口。"
  }
}

