entries.content:
{
  "name_cn": "佩洛洛斯拉",
  "name_jp": "Perorodzilla",
  "appearance": "一只如同哥斯拉般巨大的“佩洛洛”玩偶怪兽。它保留了佩洛洛（一种可爱的黄色小鸟）的卡通外形，但体型被放大了无数倍，眼神空洞，从眼中能发射出毁灭性的激光。",
  "background": "出现在D.U.近海的巨大怪兽，外形酷似Momo Friends中的人气角色“佩洛洛”。尽管外表可爱，但其存在本身就是巨大的威胁。",
  "attributes": {
    "armor_type": "特殊装甲",
    "attack_type": "神秘",
    "location": "室外/室内"
  },
  "combat_flow": {
    "summary": "战斗围绕着处理召唤物，并利用它们来反制Boss的增益机制，从而使其虚弱。",
    "phases": [
      {
        "phase_number": 1,
        "trigger": "战斗开始",
        "description": "Boss会使用多种攻击，并周期性召唤'佩洛洛小怪'。",
        "mechanics": ["主要攻击方式为直线型的'白热射线'。", "会周期性地使用'眼棱'技能为自身叠加增益Buff。", "会召唤'佩洛洛小怪'协助攻击。"]
      }
    ],
    "groggy_condition": "Boss使用'眼棱'时，玩家需要击败'佩洛洛小怪'来吸收这些'眼棱'。每吸收一个，都会填充大量无力值槽。"
  }
}

