entries.content:
---
    {
      "name_cn": "希罗尼穆斯",
      "name_jp": "Hieronymus",
      "appearance": "一个被拘束在巨大、类似古代圣物或棺材装置中的扭曲生物。它的身体大部分被机械和管线覆盖，暴露出部分发光的、类似核心的脆弱组织，整体形象充满了痛苦、神圣与亵渎的混合感。",
      "background": "在圣三一地下被遗忘的圣堂中发现的“伪圣”。据信是古代某种仪式的实验体。这个不应被唤醒的存在，如今再次活动。",
      "attributes": {
        "armor_type": "轻装甲",
        "attack_type": "爆发",
        "location": "市街/室内"
      },
      "combat_flow": {
        "summary": "战斗完全围绕'治疗'机制展开，考验队伍的治疗能力而非控制能力。",
        "phases": [
          {
            "phase_number": 1,
            "trigger": "战斗开始 (高生命值阶段)",
            "description": "战场上会出现一个绿色的'圣遗物'和一个红色的'圣遗物'。",
            "mechanics": ["红色圣遗物会对全体我方单位造成持续伤害。", "绿色圣遗物可以被我方角色'治疗'。", "Boss会使用'赎罪之光'等技能攻击。"]
          },
          {
            "phase_number": 2,
            "trigger": "HP降低到一定程度后 (低生命值阶段)",
            "description": "Boss的攻击模式会改变，技能会增强。",
            "mechanics": ["可能会出现新的圣遗物或增强现有圣遗物的效果。"]
          }
        ],
        "groggy_condition": "无常规累积方式。核心机制是通过'治疗'场上的绿色圣遗物，当对其累计治疗量达到一个阈值时，Boss会立即进入长时间的虚弱状态，受到的伤害大幅增加。"
      }
    }

