entries.content:
---
    {
      "name_cn": "切赛德",
      "name_jp": "Chesed",
      "appearance": "一个巨大的、立方体状的移动兵工厂核心。它本身没有生物特征，完全由装甲和机械构成，表面布满了炮塔和生产线开口，可以源源不断地制造并投放机器人军队。",
      "background": "“十字神名”序列第四位的预言者，一个控制着巨大兵工厂的AI。它能无限制地生产机械士兵，并将一切入侵者视为排除目标。",
      "attributes": {
        "armor_type": "重装甲",
        "attack_type": "贯通",
        "location": "室外/室内"
      },
      "combat_flow": {
        "summary": "考验队伍的持续范围清场能力（AOE），需要在Boss的即死计时器结束前将其击败。",
        "phases": [
          {
            "phase_number": 1,
            "trigger": "战斗开始",
            "description": "清小怪阶段。玩家需要在时限内击败潮水般涌来的机械士兵，并摧毁两扇巨大的闸门。",
            "mechanics": ["敌人会从多个方向大量出现。", "必须在时限内完成目标才能进入下一阶段。"]
          },
          {
            "phase_number": 2,
            "trigger": "摧毁两扇巨门后",
            "description": "直面切赛德核心。Boss本体不会移动或直接攻击，但会不断召唤大量机械士兵。",
            "mechanics": ["核心机制：Boss的ATG能量条会随时间稳定增长。", "当ATG达到100%时，释放全屏即死技能'日月无上之权能'，战斗失败。"]
          }
        ],
        "groggy_condition": "通过快速击杀Boss召唤的大量机械士兵来累积无力值。"
      }
    }

