{
  "groupProfile": {
    "id": "arius_squad",
    "name": "阿里乌斯小队 (Arius Squad)",
    "function": "阿里乌斯分校最精锐的特种作战小队，由锭前纱织领导。她们是纱织实现目的的“子弹”与“工具”，也是在残酷环境中相依为命的“家人”。小队执行着由上层（如贝阿朵莉切）下达的各种高难度破坏、渗透与暗杀任务。",
    "members": [
      {
        "name": "锭前纱织 (Jomae Saori)",
        "role": "队长。冷酷无情的指挥官，为了保护同伴可以化身恶魔。独自背负所有罪恶，是小队的决策者和绝对核心。",
        "appearance": "深蓝色短发，戴着战术便帽与遮住下半张脸的黑色口罩。眼神锐利，身着便于行动的黑色作战服，给人一种训练有素、高度警惕的印象。"
      },
      {
        "name": "秤亚津子 (Hakari Atsuko)",
        "role": "公主/精神象征。被小队成员共同守护，拥有看透事物本质的纯粹之心，是团队在绝望中维系人性的最后一道防线。",
        "appearance": "粉紫色长发，大部分面容被巨大的白色兜帽和标志性的黑色防毒面具所遮盖。使她显得神秘而难以捉摸，与其‘公主’的身份相符。实际面具下是红色眼瞳和一张柔美温柔的少女脸型，乐观积极，对他人很温柔，有献身精神。"
      },
      {
        "name": "戒野美咲 (Ikayoi Misaki)",
        "role": "狙击手。悲观的虚无主义者，将自己视作随时可以丢弃的消耗品，通过自毁倾向来确认自己的存在。",
        "appearance": "深棕色短发，红色眼瞳。通常戴着黑色口罩，只露出一双毫无生气的眼睛。身穿灰黑色的连帽夹克，散发着虚无和厌世的气息。"
      },
      {
        "name": "槌永日和 (Tsuchinaga Hiyori)",
        "role": "支援/重火力手。性格懦弱、悲观且总是道歉，但为了不拖累同伴，会鼓起勇气背负沉重的武装。",
        "appearance": "亮薄荷绿色头发，绿色眼瞳。戴着一顶白色便帽，身穿宽大的白色连帽外套。脸上总是带着一丝胆怯和不安，看起来随时都会哭出来。"
      }
    ],
    "groupDynamics": {
      "philosophy": "深受“一切皆虚无”思想的毒害，但又在此基础上诞生了“正因一切皆虚无，所以我们作为家人的羁绊是唯一真实”的矛盾信条。",
      "internalAtmosphere": "表面上是冰冷的上下级关系，但实际上成员间存在着极度深厚、超越生死的依赖感。她们的交流方式直接而残酷，却是废墟中唯一的温情所在。"
    }
  }
}

