entries.content:
---
{
  "groupProfile": {
    "id": "gematria",
    "name": "盖玛特里亚 (Gematria)",
    "function": "一个来自基沃托斯外部的神秘结社，由数名非人的“大人”组成。他们痴迷于探究“神秘”、“恐惧”与“崇高”等抽象概念的本质，并将整个基沃托斯视为实验场，将学生视为研究材料。他们是引发诸多重大事件的幕后黑手，也是与老师（玩家）对立的“坏大人”的代表。",
    "members": [
      {
        "name": "黑服 (Black Suit)",
        "role": "考古学家与契约大师。组织的对外发言人，经常与老师接触。",
        "appearance": "主体为人形的黑色阴影，仿佛穿着一套合身的西装。从身体的裂缝中透出苍白的光芒，头部持续散发着黑烟，形象诡异而不祥。",
        "methods": "擅长利用规则、契约和语言逻辑的漏洞来达成目的。他对古代技术与无名之神的遗迹抱有浓厚兴趣，认为学生的“神秘”是基沃托斯最宝贵的研究素材。 [1, 5]",
        "attitude": "对老师抱有一种扭曲的同类感，认为双方都是引导者，只是方式不同。他遵守自己定下的规则，在不择手段的同时也表现出一种独特的绅士风度。"
      },
      {
        "name": "大师 (Maestro)",
        "role": "艺术家与造物主。热衷于将抽象概念（如恐惧、神圣）具现化为实体造物。",
        "appearance": "一个诡异的双头木偶，身体穿着蓝色燕尾服。左边的头只有一只眼睛，右边的头只有嘴巴，脸上布满裂纹，给人以残缺和疯狂的艺术感。 [3]",
        "methods": "总力战Boss“耶罗尼姆斯”、“白与黑”等都是其“艺术作品”。他鄙视将艺术单纯用作武器的行为，对自己的创作抱有极高的热情和自负。 [3, 4]",
        "attitude": "将老师视为能理解自己艺术的“鉴赏家”，对老师使用“大人的卡片”这一未知行为抱有强烈的好奇心。"
      },
      {
        "name": "戈尔孔达 & 什一之图 (Golconde & Decalcomanie)",
        "role": "诠释者与观察者。专注于解读“文本”与“符号”，是悲剧的鉴赏家。",
        "appearance": "这是一个二人一体的存在。什一之图是一个没有头颅、身穿风衣的身体，负责捧着戈尔孔达——一个装在画框里的头颅。戈尔孔达负责思考与交谈，而什一之图则几乎不说话，只在关键时刻予以肯定。",
        "methods": "将世界视为一部戏剧，痴迷于观察和诠释在苦难与悲剧中闪耀的人性光辉。他们认为悲剧是文学的极致，并试图引导事态向更具“美感”的悲剧发展。",
        "attitude": "将老师视为与自己对立的“文学流派”，即创作“奇迹”与“幸福结局”的作者，并对这种分歧抱有兴趣。"
      },
      {
        "name": "贝阿朵莉切 (Beatrice)",
        "role": "篡夺者与支配者（已被放逐）。是阿里乌斯的幕后黑手，迷恋通过谎言与欺骗窃取他人的崇高与信仰。",
        "appearance": "是盖玛特里亚中外表最接近人类的成员，一位身着白色正装、皮肤猩红的贵妇人，气质优雅但眼神中充满疯狂与恶意。 ",
        "methods": "与其他成员不同，她对研究没有兴趣，只热衷于通过精神控制（如对阿里乌斯学生灌输虚无主义）和阴谋来窃取力量，并试图彻底摧毁老师。",
        "attitude": "唯一一个纯粹敌视老师的成员，认为老师是必须被彻底排除的障碍。因其极端手段与其他成员的理念产生冲突，最终被组织清除。"
      }
    ],
    "groupDynamics": {
      "philosophy": "组织内部不存在上下级关系，成员之间基于各自的研究领域展开合作或竞争。他们都认同“不择手段地探究真理”这一核心理念，但对具体方法论存在分歧。",
      "internalAtmosphere": "成员间相互尊重对方的研究，但关系松散且互相戒备。他们会召开会议交流情报，但各自的计划都是独立进行的。对于破坏研究根基的行为（如贝阿朵莉切试图引入“色彩”），组织会毫不犹豫地予以清除。"
    }
  }
}

