{
  "wcosmic_threat": {
    "id": "the_color",
    "name": "色彩 (The Color)",
    "classification": "超验存在 / 宇宙级灾害 (Transcendental Existence / Cosmic Calamity)",
    "nature": {
      "origin": "与老师及格黑娜相同，同属'基沃托斯之外'的存在。",
      "ambiguity": "其大部分信息尚不明确，连它究竟是实体、存在还是概念都无从得知。",
      "quotes": {
        "beatrice": "不被诠释、不被理解、不被沟通——仅仅是不祥降临之光；无法理解其目的与意图的不可解观念。",
        "sisterhood_texts": "令人陷入疯狂的光。"
      }
    },
    "visual_manifestation": {
      "form": "并无固定实体，被形容为光，也确实会投射出紫色光芒。",
      "description": "其视觉形象难以名状——有时如同黑洞般中央敞开着空洞，有时又似日全食及其外围环状结构，呈现出既像日冕又似日珥的形态。"
    },
    "objective": "将其自身的“色彩”覆盖整个世界，将基沃托斯学生们所持有的“神秘”与“崇高”反转为“恐怖”。它的最终目的并非征服或毁灭，而是彻底的同化与替代。",
    "methods": {
      "corruption": "通过接触，污染并扭曲目标的本质，将其从神圣的存在反转为恐怖的怪物。例如，“白子＊恐惧”的力量根源就与“色彩”的侵蚀有关。",
      "harbingers": "在被侵蚀的世界中挑选或创造代理人，即“色彩的先锋”，作为其意志的执行者和物理化身。",
      "reality_incursion": "直接降临，形成名为“色彩圣所”的领域，将其所在区域的物理法则改写为自己的规则，是其入侵世界的滩头阵地。"
    },
    "relation_to_others": {
      "to_kivotos": "绝对的、无法共存的生存威胁。是所有学生和派系必须共同面对的终极天灾，因为它从根本上否定了“青春”与“奇迹”的存在。",
      "to_gematria": "一个失控的、会彻底摧毁实验场的灾难性变量。除贝阿朵莉切外，所有成员都视其为必须排除的干扰，因为它会毁掉他们珍视的研究对象——基沃托斯的“神秘”。",
      "to_beatrice": "贝阿朵莉切曾试图引入并利用它的力量来实现自己篡夺“崇高”的目的，但最终被其反噬，证明了“色彩”无法被凡人所控制。",
      "to_player": "老师是保护、引导学生“神秘”之人，而“色彩”是侵蚀、反转“神秘”之物。两者在哲学层面上是绝对的、不可调和的对立面。"
    }
  }
}

