entries.content:
## 队伍详情
[系统提示：以下是已注册到关系列表的学生变量状态，请根据此信息进行回应和操作。新增变量对象时，必须参照以下已有的json字段格式编写]

<%= await(async () => {
    /* ========================================
     * 【选择性加载 relationship_students】
     * 策略：
     *   1. 完整加载：附近的学生 (is_nearby=true) 或 队伍成员 (is_in_team=true)
     *   2. 简略加载：其他学生仅加载部分字段
     *   3. 立即加载貌似重新生成会读到生成前的era变量，但EJS没法监听事件延后加载，貌似也没啥好办法
     * ======================================== */

    try {
        console.log('=== 开始选择性加载 relationship_students ===');

        // ========== 读取数据 ==========
        const worldInfo = getvar('stat_data.world_info', { scope: 'local', clone: true }) || {};
        const relStudents = getvar('stat_data.relationship_students', { scope: 'local', clone: true }) || {};

        const currentLocation = worldInfo?.location?.detailed_location || 
                               worldInfo?.location?.district || '未知地点';

        console.log(`【当前地点】${currentLocation}`);

        // ========== 构建选择性加载的学生数据 ==========
        const filteredStudents = {};
        const allNames = Object.keys(relStudents).filter(k => k && k.charCodeAt(0) !== 36);

        console.log(`【学生总数】${allNames.length}人`);

        let fullCount = 0;
        let partialCount = 0;

        for (const name of allNames) {
            const student = relStudents[name] || {};
            const isNearby = student.location_info?.is_nearby === true;
            const inTeam = student.basic_info?.is_in_team === true;

