<%= await (async () => {
    /* =======================
     * 【功能】根据附近3楼是否匹配角色（简称），一次性输出NSFW列表、SFW列表与插图指南
     * - 统一加载世界书中的角色简称映射、SFW/NSFW插图数据库、插图指南
     * - 仅检索附近3楼的聊天内容
     * - 命中角色后同时输出所需数据（JSON格式）
     * ======================= */

    const log = (s) => {
      try { console.log(`[插图合集加载] ${s}`); } catch (_) {}
    };

    const loadWorldInfoJSON = async (entryName) => {
      const raw = String(await getWorldInfo(entryName));
      if (!raw) {
        throw new Error(`世界书条目不存在或为空: ${entryName}`);
      }
      const cleaned = raw.replace(/^\s*```(?:json)?\s*([\s\S]*?)\s*```/i, '$1');
      return JSON.parse(cleaned);
    };

    let NSFW_DATABASE = {};
    let SFW_DATABASE = {};
    let CHAR_NICKNAME_MAP = {};
    let GUIDE_DATA = {};

    try {
      NSFW_DATABASE = await loadWorldInfoJSON('nsfw_image_database');
      SFW_DATABASE = await loadWorldInfoJSON('sfw_image_database');
      CHAR_NICKNAME_MAP = await loadWorldInfoJSON('character_nickname_map');
      GUIDE_DATA = await loadWorldInfoJSON('image_insertion_guide');
    } catch (e) {
      const emptyOutput = '{}';
      log(`匹配0个角色，输出${emptyOutput.length}字符`);
      return emptyOutput;
    }

    const RECENT_FLOORS = 3;
    let recentMessages = [];
    try {
      const messages = getChatMessages(RECENT_FLOORS) || [];
      recentMessages = Array.isArray(messages) ? messages : [messages];
    } catch (e) {
      // 忽略，保持空数组
    }
    const normalizedMessages = recentMessages.map(msg => String(msg || '').toLowerCase());

    const matchedChars = [];
    for (const [charName, nicknames] of Object.entries(CHAR_NICKNAME_MAP)) {
      if (!Array.isArray(nicknames)) {
        continue;
      }
      const hit = nicknames.some(nickname => {
        const nicknameLower = String(nickname || '').toLowerCase();
        return normalizedMessages.some(message => message.includes(nicknameLower));
      });
      if (hit) {
        matchedChars.push(charName);
      }
    }

    if (matchedChars.length === 0) {
      const emptyOutput = '{}';
      log(`匹配0个角色，输出${emptyOutput.length}字符`);
      return emptyOutput;
    }

    const pickMatched = (database) => matchedChars.reduce((acc, charName) => {
      if (database[charName]) {
        acc[charName] = database[charName];
      }
      return acc;
    }, {});

    const outputData = {
      nsfw_image: pickMatched(NSFW_DATABASE),
      sfw_image: pickMatched(SFW_DATABASE),
      insertion_guide: GUIDE_DATA
    };

    const jsonOutput = JSON.stringify(outputData, null, 2);
    log(`匹配${matchedChars.length}个角色，输出${jsonOutput.length}字符`);
    return jsonOutput;
  })() %>

